/* VAYRATHEN — js/data/lore.js
   A short field note for every monster: what the real animal does (or which Thai, Khmer or Himmapan legend the
   creature comes from) and how it behaves in the realm. MOB_LORE[id] = [th, en]; shown on the wiki monster page
   and in the target tooltip. Every monster has its own text (tests/data.test.js checks it). */
'use strict';

const MOB_LORE = {
  /* ---------- Aren and the Suwannin fields ---------- */
  dewblob:["หยดน้ำค้างยามเช้าบนยอดข้าวที่รวมตัวกันจนมีชีวิต ตัวใสเย็นและนิ่มเหมือนวุ้น เมื่อแดดสายก็หลบเข้าเงาร่มไม้ริมคันนา", "Morning dew on the rice tips that pooled together and came alive, cool, clear and soft as agar. It hides in the shade of the paddy dykes once the sun climbs."],
  hare:["กระต่ายป่าพันธุ์ทุ่งที่มีเห็ดงอกบนหัวจากสปอร์ในฟางเปียก ออกหากินตอนเช้ามืดและพลบค่ำเหมือนกระต่ายป่าจริง วิ่งซิกแซกเมื่อถูกไล่", "A field hare with a mushroom sprouting from its head, seeded by spores in the wet straw. Like real hares it feeds at dawn and dusk and zig-zags when chased."],
  boar:["หมูป่าที่ชอบขุดรากหญ้าและหัวมันตามขอบทุ่งจนขนติดสีฟางทอง ตัวผู้มีเขี้ยวคมงอกโค้งขึ้นใช้งัดดินและต่อสู้ หากจนมุมจะพุ่งชนอย่างไม่กลัวตาย", "A wild boar that roots up grass and tubers along the field edges until its bristles take the gold of the straw. Its upcurved tusks dig and fight, and a cornered boar charges without fear."],
  lantern:["โคมลอยที่ปล่อยขึ้นฟ้าในคืนยี่เป็งแล้วตกลงกลางทุ่ง ไฟในโคมไม่ยอมดับเพราะคำอธิษฐานที่ผูกไว้ยังไม่สมหวัง จึงลอยวนหาเจ้าของ", "A sky lantern released on the night of Yi Peng that fell back into the fields. The wish tied to it never came true, so its flame will not die and it drifts about looking for its owner."],
  boss:["เจลลี่น้ำค้างนับพันที่หลอมรวมกันใต้แสงจันทร์จนกลายเป็นราชาตัวโต สวมมงกุฎทองที่ชาวนาทำหายในโคลน เรียกลูกน้ำค้างออกมาช่วยรบและฟื้นตัวเองได้", "A thousand dew jellies merged under the moon into one bloated king wearing a gold crown some farmer lost in the mud. It calls out little dew jellies to fight and can heal itself."],
  kaipa:["บรรพบุรุษของไก่บ้านทั่วโลก ตัวผู้มีขนสร้อยคอสีส้มทอง หงอนแดง และหางโค้งสีเขียวเหลือบดำ ไก่ป่าสายนี้มีตุ้มหูสีแดงแบบที่พบทางเหนือและตะวันตกของไทย ขันเสียงสั้นกว่าไก่บ้านและบินหนีขึ้นต้นไม้ได้", "The wild ancestor of every chicken on earth: the cock wears golden-orange hackles, a red comb and a glossy green-black sickle tail. This strain has the red ear lobes of northern and western Thailand, a shorter crow than a farm rooster, and flies up into trees when startled."],
  kobna:["กบนาหรือกบจีน ผิวขรุขระมีปุ่มและจุดสีเข้ม ส่งเสียงร้องดังระงมหลังฝนแรกของฤดู ชาวบ้านจับมาทำอาหารมาแต่โบราณ ตัวที่นี่จะกระโดดหนีลงน้ำทันทีที่เห็นคน", "The East Asian paddy frog, warty and dark-spotted, whose chorus fills the fields after the first rains; villagers have caught it for food for centuries. The ones here leap for the water the moment they see a person."],
  /* ---------- 1 Whispering Bamboo ---------- */
  bamboomonkey:["ลิงแสมที่อาศัยในดงไผ่ หากินเป็นฝูงใหญ่และมีจ่าฝูงคอยคุม ขึ้นชื่อเรื่องแย่งอาหารนักเดินทาง ฝูงนี้เรียนรู้ที่จะเหวี่ยงตัวไปตามลมที่พัดลำไผ่จนเร็วเกินตาตาม", "Long-tailed macaques of the bamboo groves, living in big troops under one alpha and notorious for snatching travellers' food. This troop has learned to swing on the wind that bends the culms, faster than the eye can follow."],
  junglefowl:["ไก่ฟ้าพญาลอ นกประจำชาติไทย ตัวผู้มีหน้าสีแดงสด หงอนเป็นพู่ขนสีดำ ลำตัวสีเทาและหลังส่วนล่างสีส้มเหมือนไฟจึงได้ชื่อว่าหลังไฟ เดินหากินบนพื้นป่าเป็นคู่หรือกลุ่มเล็ก ตัวผู้จะตีปีกเสียงดังขู่ผู้บุกรุก", "The Siamese fireback, Thailand's national bird: the cock has a scarlet face, a tuft of black crest plumes, grey body and a fiery orange lower back that gives it its name. It forages on the forest floor in pairs or small groups, and the male whirs his wings loudly to warn off intruders."],
  greenviper:["งูเขียวหางไหม้ งูพิษที่พบบ่อยที่สุดในไทย ตัวเขียวสด ปลายหางสีน้ำตาลแดงเหมือนถูกไฟลน มีแอ่งรับความร้อนระหว่างตากับจมูกจึงฉกเหยื่อได้แม่นแม้ในความมืด ชอบซุ่มนิ่งบนกิ่งไผ่แล้วฉกคนที่เดินผ่าน", "The white-lipped green pit viper, the venomous snake most often met in Thailand: bright green with a rusty tail tip that looks scorched. Heat-sensing pits between eye and nostril let it strike true in the dark, and it waits motionless on bamboo stems for anyone who brushes past."],
  bamboogrub:["หนอนรถด่วนหรือหนอนไผ่ ตัวอ่อนของผีเสื้อกลางคืนที่กินเยื่อในลำไผ่ คนเหนือนำมาทอดเป็นอาหาร ตัวนี้กินไผ่จนอ้วนเท่าท่อนซุงและคืบช้าแต่ทนทานมาก", "The bamboo caterpillar, larva of a moth that eats the pith inside bamboo culms and is fried as a snack in northern Thailand. This one ate until it grew as thick as a log: slow, but very hard to kill."],
  bamboojackal:["หมาจิ้งจอกทองที่หากินเป็นคู่หรือครอบครัวเล็ก ๆ ตามชายป่า เสียงหอนแหลมยามค่ำเป็นสัญญาณเรียกฝูง ตัวในป่าไผ่นี้ล่าเป็นทีมและวิ่งเร็วเกินคาด", "The golden jackal, hunting in pairs or small families along the forest edge; its shrill evening howl calls the group together. The bamboo jackals hunt as a team and run faster than you expect."],
  termiteshroom:["เห็ดโคนที่งอกจากรังปลวกหลังฝนต้นฤดู หมวกแหลมสีน้ำตาลอ่อนบานบนก้านยาว ปลวกเพาะเชื้อราชนิดนี้ไว้ในรังเป็นอาหาร ดอกที่นี่ดูดพลังจากรังปลวกจนลุกขึ้นเดินได้", "Termite mushrooms that burst from termite mounds after the first rains, pale brown pointed caps on long stems. Termites farm this fungus inside their nests as food; these ones drank so much from the mound that they got up and walked."],
  /* ---------- 2 Red Lotus Marsh ---------- */
  goldfrog:["กบลายทองที่มีแถบสีเหลืองทองพาดหลังเหมือนกบหลายชนิดในนาไทย แถบนี้ช่วยพรางตัวกับหญ้าแห้งริมบึง ร้องเสียงทุ้มเป็นจังหวะตลอดคืน", "A frog with a golden stripe down its back like several real Thai paddy frogs; the stripe hides it among dry marsh grass. It croaks a deep steady beat all night."],
  giantleech:["ปลิงควายที่โตจนยาวเท่าแขน ปลิงจริงมีปากดูดสองด้าน ปล่อยสารกันเลือดแข็งตัวจึงกัดแล้วแทบไม่รู้สึก มันว่ายเป็นคลื่นเข้าหาแรงสั่นสะเทือนในน้ำ", "A buffalo leech grown as long as an arm. Real leeches have suckers at both ends and inject an anticoagulant so their bite is barely felt; this one swims in ripples toward any splash in the water."],
  egret:["นกยางเปียที่ยืนนิ่งริมบึงแล้วพุ่งคอแทงปลาเร็วเหมือนหอก ฤดูผสมพันธุ์มีขนเปียยาวพลิ้วที่ท้ายทอย ตัวที่นี่ตัวโตและไม่กลัวคน", "The little egret, standing still at the water's edge then stabbing its neck out at fish like a spear; in breeding season it grows long plumes on its nape. The egrets here are big and unafraid of people."],
  paddycrab:["ปูนาตัวสีดำคล้ำที่ขุดรูตามคันนา ชาวนามองว่าเป็นศัตรูกัดต้นกล้า แต่ก็จับมาทำปูดองใส่ส้มตำ กระดองแข็งมากและหนีลงรูได้เร็ว", "The dark rice-field crab that burrows into paddy dykes. Farmers curse it for nipping seedlings but also pickle it for papaya salad. Its shell is very hard and it bolts into its hole fast."],
  paddyturtle:["เต่านาหรือเต่ากินหอย หัวโตมีแถบสีครีม กระดองสีน้ำตาลมีสันนูน อาศัยในนาข้าวและหนองบึง กินหอยโข่งเป็นอาหารหลัก ตัวที่นี่หดหัวเข้ากระดองทันทีที่ถูกตี", "The Malayan snail-eating turtle: a big head with cream stripes and a ridged brown shell, living in rice paddies and swamps and eating mostly apple snails. These ones pull their heads in the moment they are hit."],
  lotusjelly:["วุ้นที่เกิดจากน้ำเมือกในก้านบัวแดง บัวสายจริงบานกลางคืนและหุบตอนสาย วุ้นตัวนี้จึงตื่นตัวที่สุดตอนพลบค่ำ", "A jelly born from the slime inside red water-lily stems. Real red water lilies open at night and close by late morning, so this jelly is liveliest at dusk."],
  waterwraith:["ผีพรายน้ำ วิญญาณคนจมน้ำตายตามความเชื่อไทย ผมยาวเปียกปรกหน้า เชื่อกันว่ามันดึงขาคนลงไปใต้น้ำเพื่อหาตัวแทน ตัวนี้ลอยขึ้นจากบึงบัวในคืนเดือนมืด", "The phrai nam of Thai belief, the ghost of someone who drowned, with long wet hair over its face. It is said to drag swimmers down by the ankle to take its place; this one rises from the lotus marsh on moonless nights."],
  /* ---------- 3 Chao Phraya Riverside ---------- */
  watermonitor:["ตะกวดหรือเหี้ย กิ้งก่ายักษ์ที่ว่ายน้ำเก่ง ยาวได้ถึงสองเมตร กินซากและเหยื่อแทบทุกอย่าง เป็นตัวช่วยกำจัดซากในเมือง ตัวนี้ใช้หางฟาดแรงพอทำให้คนล้ม", "The Asian water monitor, a swimming lizard up to two metres long that eats carrion and almost anything else, cleaning up the canals of Bangkok. This one swings its tail hard enough to knock a man down."],
  riverotter:["นากเล็กเล็บสั้น นากที่ตัวเล็กที่สุดในโลก อยู่เป็นครอบครัว ใช้มือคล่องแคล่วงมหาปูและหอย ส่งเสียงร้องสื่อสารกันตลอดเวลา ตัวที่นี่ว่องไวมากทั้งบนบกและในน้ำ", "The Asian small-clawed otter, the smallest otter in the world. It lives in family groups, feels for crabs and snails with nimble paws and chatters constantly. On land or in water it is very quick."],
  forestcobra:["งูเห่าไทยหรืองูเห่าหม้อ แผ่แม่เบี้ยแล้วขู่ฟ่อเสียงดัง หลังแม่เบี้ยมีลายวงกลมคล้ายแว่นข้างเดียว พิษทำลายระบบประสาท ตัวที่นี่พ่นพิษได้ไกลเหมือนงูเห่าพ่นพิษสยาม", "The monocled cobra, which spreads its hood and hisses loudly; the back of the hood bears a single ring like a monocle. Its venom attacks the nerves, and this one can spit it at range like the Indochinese spitting cobra."],
  firekingfisher:["นกกระเต็นอกขาว สีฟ้าสดตัดกับอกส้มแดงและปากแดงเหมือนถ่านไฟ เกาะนิ่งริมน้ำแล้วพุ่งดิ่งลงจับปลา ตัวนี้พุ่งตัวเร็วจนเกิดประกายไฟ", "Like the white-throated kingfisher, electric blue with a rust-orange breast and a beak red as an ember. It perches still by the river then plunges for fish, and this one dives so fast it throws sparks."],
  wildbuffalo:["ควายป่า บรรพบุรุษของควายบ้าน ตัวใหญ่ดุกว่ามาก เขาโค้งกว้างที่สุดในบรรดาสัตว์มีเขา ขาท่อนล่างสีขาวหม่น ในไทยเหลือเพียงฝูงเล็กที่ห้วยขาแข้ง ตัวผู้ชนอย่างไม่ลังเล", "The wild water buffalo, ancestor of the farm buffalo but bigger and far fiercer, with the widest horn span of any living animal and dirty-white lower legs. Only a small herd survives in Thailand, at Huai Kha Khaeng; bulls charge without hesitation."],
  waterbug:["แมงดานา แมลงน้ำตัวใหญ่ที่ใช้ขาหน้าหนีบจับลูกปลาและกบแล้วฉีดน้ำย่อยเข้าไป ตัวผู้มีกลิ่นหอมจนคนไทยนำมาตำน้ำพริกแมงดา", "The giant water bug, which grips tadpoles and small fish with its front legs and injects digestive juice. The males smell so fragrant that Thais pound them into chilli paste."],
  /* ---------- 4 Abandoned Floating Market ---------- */
  boatscarecrow:["หุ่นฟางที่แม่ค้าเคยตั้งไว้ไล่นกบนหัวเรือ สวมงอบใบลาน เมื่อตลาดร้างไปมันยังเฝ้าเรือไม่ยอมเลิก ใช้ไม้ถ่อเรือฟาดใครก็ตามที่เข้าใกล้", "A straw figure the vendors once stood on their bows to scare off birds, still wearing its palm-leaf ngob hat. The market died but it never stopped guarding the boat, and it swings a punting pole at anyone who comes near."],
  phantommerchant:["วิญญาณแม่ค้าที่จมน้ำตายตอนเรือล่มกลางตลาด ยังพายเรือขายของในหมอกยามเช้าเหมือนเดิม ใครไปต่อราคาจะถูกตามไปไม่ปล่อย", "The ghost of a market woman who drowned when her boat capsized, still paddling her wares through the morning mist. Haggle with her and she follows you and will not let go."],
  boatlamp:["ตะเกียงน้ำมันก๊าดที่แขวนท้ายเรือแจว ไฟสีเขียวซีดของมันมาจากก๊าซหนองน้ำที่ลุกติดเอง ชาวบ้านเรียกผีกระสือน้ำ มันยิงลูกไฟใส่คนที่พายเรือผ่าน", "A kerosene lamp that hung from a sampan's stern. Its pale green flame is marsh gas that lights itself, which villagers blame on ghosts, and it hurls fireballs at passing boats."],
  pierrat:["หนูท่อตัวโตที่อาศัยใต้ท่าเรือไม้ ว่ายน้ำได้ ฟันแทะไม้และสายไฟขาดได้ อยู่กันเป็นฝูงใหญ่และกัดอย่างไม่กลัวคน", "Fat brown rats living under the wooden piers. Like real Norway rats they swim well, gnaw through wood and wiring, gather in big colonies and bite without fear of people."],
  watersnake:["งูปลิง งูน้ำหน้าบวมที่อาศัยตามคลองและป่าชายเลน ตาและรูจมูกอยู่บนหัวจึงซุ่มใต้น้ำได้นาน มีพิษอ่อน ตัวที่นี่พันเสาท่าเรือรอปลาและนักเดินทาง", "The puff-faced water snake of canals and mangroves; its eyes and nostrils sit on top of its head so it can lie under water for a long time. Mildly venomous, it coils round the pier posts waiting for fish and travellers."],
  sabercrab:["ปูก้ามดาบ ตัวผู้มีก้ามข้างหนึ่งใหญ่ผิดส่วนสีส้มสด ใช้โบกเรียกตัวเมียและขู่คู่แข่ง ตามีก้านยื่นสูงจึงมองเห็นรอบตัวเมื่ออยู่บนเลน ตัวนี้ใช้ก้ามใหญ่หนีบแรงกว่าคีม", "A fiddler crab: the male waves one huge orange claw to court females and warn off rivals, and its eyes sit on tall stalks to look across the mudflat. This one's big claw pinches harder than pliers."],
  /* ---------- 5 Forest Temple Ruins ---------- */
  stuccoyaksha:["รูปปั้นยักษ์ปูนปั้นที่ยืนเฝ้าประตูวัด ช่างโบราณผสมปูนขาวกับทรายและกาวหนังสัตว์ปั้นทับโครงอิฐ เมื่อวัดร้างไร้คนดูแล มันก็ออกเดินตรวจลานวัดเอง", "A stucco yaksha that guarded the temple gate, moulded by old craftsmen from lime, sand and hide glue over a brick core. With no monks left to tend the temple, it now patrols the courtyard on its own."],
  stonesingha:["สิงห์หินคู่หน้าโบสถ์ที่ผุกร่อนจนร้าวทั้งตัว สิงห์ไทยเป็นสัตว์หิมพานต์ที่ดัดแปลงจากสิงโตในคติอินเดีย ทำหน้าที่ปกป้องศาสนสถาน ตาสีทองยังลุกวาวเมื่อมีคนแปลกหน้าเข้ามา", "One of the pair of stone singha before the ordination hall, weathered and cracked all over. The singha is the Himmapan lion adapted from Indian lore, a guardian of holy places, and its golden eyes still flare at strangers."],
  chapelbat:["ค้างคาวแม่ไก่ ค้างคาวกินผลไม้ตัวใหญ่ที่สุดในไทย หน้าเหมือนสุนัขจิ้งจอก มีขนคอสีส้ม ชอบเกาะห้อยหัวเป็นฝูงใหญ่บนต้นไม้ในวัดซึ่งปลอดภัยจากคนล่า เช่นที่วัดโพธิ์บางคล้า", "Lyle's flying fox, Thailand's biggest fruit bat, with a fox-like face and an orange collar of fur. Big colonies roost upside-down in temple trees where nobody hunts them, as at Wat Pho Bang Khla."],
  lankypreta:["เปรตในคติพุทธ ผีที่ทำบาปไว้จึงตัวสูงเท่าต้นตาล ผอมแห้ง ปากเล็กเท่ารูเข็มกินอะไรไม่ได้ ร้องเสียงหวีดขอส่วนบุญในวันสารทเดือนสิบ", "A preta of Buddhist belief: a sinner reborn as a ghost tall as a sugar palm, starved thin, with a mouth no wider than a needle's eye so it can never eat. It shrieks for merit on the tenth-month festival."],
  goldgecko:["ตุ๊กแกที่ร้องตุ๊กแก ๆ ดังลั่นในเวลากลางคืน ตุ๊กแกจริงตัวสีเทาฟ้ามีจุดส้ม กัดแล้วไม่ยอมปล่อย ตัวนี้อาศัยในวิหารจนเกล็ดซึมสีทองจากองค์พระ", "A tokay gecko that calls its own name, to-kay, loudly at night. Real tokays are blue-grey with orange spots and will not let go once they bite; this one lived in the vihara so long its scales soaked up the gold leaf."],
  offeringsquirrel:["กระรอกหลากสีที่คุ้นกับคนในวัด ชอบขโมยกล้วยและข้าวเหนียวจากพานไหว้ ปีนเร็ว กระโดดข้ามกิ่งได้ไกล ใช้หางเป็นตัวถ่วงสมดุล", "A variable squirrel grown bold around the monks, stealing bananas and sticky rice from the offering trays. It climbs fast and leaps far between branches, using its tail for balance."],
  templelantern:["โคมกระดาษสาแบบล้านนาที่แขวนในวิหารช่วงยี่เป็ง เมื่อไม่มีใครมาจุดบูชาอีก โคมก็ลุกไฟเองด้วยแรงศรัทธาที่ค้าง ส่องแสงศักดิ์สิทธิ์ใส่ผู้ไม่เคารพ", "A Lanna paper lantern hung in the vihara for Yi Peng. With nobody left to light it, it kindles itself on leftover devotion and blasts holy light at the disrespectful."],
  /* ---------- 6 Chiang Dao Caves ---------- */
  vampirebat:["ค้างคาวแวมไพร์แปลงใหญ่ หูใหญ่ติดกัน จมูกมีแผ่นหนังรูปใบไม้ไว้ส่งคลื่นเสียง ไม่ได้ดูดเลือดแต่ล่ากบ จิ้งจก และค้างคาวตัวเล็กกว่า ตัวในถ้ำนี้กลับกระหายเลือดจริง ๆ", "The greater false vampire bat: huge joined ears and a leaf-shaped nose for echolocation. Real ones do not drink blood but hunt frogs, geckos and smaller bats; the ones in this cave really have learned to thirst for blood."],
  giantscorpion:["แมงป่องช้าง แมงป่องสีดำตัวโตที่สุดของไทย ยาวกว่าฝ่ามือ ก้ามใหญ่แต่พิษไม่แรง จะยกหางขู่ก่อนต่อย ใต้แสงยูวีตัวจะเรืองแสงสีฟ้าเขียว", "The Asian forest scorpion, Thailand's biggest, longer than a palm, with heavy claws but mild venom. It raises its tail in warning before it stings, and glows blue-green under ultraviolet light."],
  cavespider:["ต่อที่ทำรังในถ้ำลึกมาหลายชั่วอายุจนตัวซีดจาง บินในความมืดได้ด้วยหนวดที่รับกลิ่นและแรงสั่นสะเทือน ต่อจริงทำรังจากเยื่อไม้ที่เคี้ยวผสมน้ำลายจนเป็นกระดาษ", "A hornet whose nest has hung in the deep cave for generations, until its colours faded. It flies in the dark by its antennae, which feel smell and vibration; real hornets build their nests of wood chewed into paper."],
  stalagwalker:["หินงอกที่เกิดจากหินปูนในน้ำหยดสะสมทีละนิด ราวหนึ่งเซนติเมตรต่อร้อยปี แท่งนี้งอกมาเป็นหมื่นปีจนมีวิญญาณถ้ำสิงอยู่และลุกขึ้นเดิน", "A stalagmite grown from lime in dripping water, about a centimetre a century. This one took tens of thousands of years, long enough for a cave spirit to move in and make it walk."],
  firemillipede:["กิ้งกือกระบอกยักษ์ตัวแดงดำ กิ้งกือจริงม้วนตัวกลมเมื่อถูกรบกวนและปล่อยสารเคมีกลิ่นฉุนที่ทำให้ผิวไหม้ ตัวในถ้ำนี้ร้อนจนสารนั้นลุกเป็นไฟ", "A giant red-and-black millipede. Real millipedes curl up when disturbed and ooze pungent chemicals that burn the skin; this cave millipede runs so hot its defence bursts into flame."],
  minerspirit:["วิญญาณคนงานเหมืองที่ติดอยู่ในถ้ำเมื่อปล่องถล่ม ยังสวมหมวกและตะเกียงหน้าผากเดินหาทางออกไม่หยุด ลมหายใจเย็นเยียบของมันกลายเป็นเกล็ดน้ำแข็ง", "The ghost of a miner trapped when a shaft collapsed, still wearing his helmet and brow lamp as he searches for a way out. His breath is so cold it freezes into shards of ice."],
  /* ---------- 7 Misty Highlands ---------- */
  serow:["เลียงผา สัตว์ป่าสงวนของไทย ตัวสีดำมีแผงคอสีขาว เขาสั้นแหลม ปีนหน้าผาชันได้คล่องเหมือนแพะภูเขา อยู่ตัวเดียวบนยอดดอยหินปูน", "The mainland serow, a protected species in Thailand: black with a pale mane and short spiked horns, scaling sheer cliffs like a mountain goat. It lives alone on limestone peaks."],
  blackbear:["หมีควายหรือหมีดำเอเชีย มีขนรูปตัววีสีขาวที่อก ปีนต้นไม้เก่ง ชอบกินน้ำผึ้งและผลไม้ หมีจริงหลบหน้าคนแต่ถ้าตกใจระยะใกล้จะลุกขึ้นตบอย่างรุนแรง", "The Asiatic black bear, with a white V on its chest. It climbs well and loves honey and fruit; real bears avoid people but, surprised at close range, rear up and maul."],
  cloudedleopard:["เสือลายเมฆ ลายดำบนตัวเหมือนก้อนเมฆ มีเขี้ยวยาวที่สุดเมื่อเทียบขนาดตัวในบรรดาแมวทั้งหมด ไต่ต้นไม้ลงหัวทิ่มได้ ซุ่มโจมตีจากกิ่งไม้ในหมอก", "The clouded leopard, marked with cloud-shaped blotches and the longest canines for its size of any cat. It can climb down trees head-first, and here ambushes from branches in the mist."],
  hornbill:["นกเงือกกรามช้าง ปากใหญ่มีโหนกเป็นริ้ว ตัวผู้มีถุงคอสีเหลือง เป็นคู่ผัวเดียวเมียเดียวตลอดชีวิต ตัวเมียขังตัวเองในโพรงไม้ขณะกกไข่ เสียงปีกบินดังวืดได้ยินไกลหลายร้อยเมตร", "The wreathed hornbill: a huge bill with a ridged casque, and the male has a yellow throat pouch. Pairs mate for life and the female seals herself into a tree hollow to nest; its wingbeats whoosh audibly hundreds of metres away."],
  mistspirit:["ทะเลหมอกบนยอดดอยที่จับตัวเป็นก้อนเมฆมีหน้าตา ชาวเขาเชื่อว่าผีดอยอาศัยในหมอกยามเช้า ใครหลงทางในหมอกอาจถูกพาวนไม่ได้กลับ", "Morning mist off the peaks gathered into a cloud with a face. Hill peoples believe mountain spirits ride the dawn fog, and those who wander into it may be led in circles forever."],
  kongkoi:["ผีกองกอย ผีป่าในความเชื่อทางเหนือและอีสาน ตัวเล็กขนดก มีขาข้างเดียว กระโดดได้ไกล ร้องเสียงกองกอย ๆ ตอนกลางคืนและดูดเลือดจากนิ้วเท้าคนที่หลับในป่า", "The phi kong koi of northern and Isan belief, a small shaggy forest ghost that hops far on one leg, cries kong-koi at night and sucks blood from the toes of people asleep in the jungle."],
  /* ---------- 8 Old Temple Cemetery ---------- */
  krasue:["กระสือ ผีหญิงที่ถอดหัวออกจากร่างตอนกลางคืน ลอยไปพร้อมไส้และอวัยวะที่ห้อยระย้าเรืองแสง หากินของสกปรกและเลือดสด กลับเข้าร่างก่อนรุ่งสาง", "The krasue, a woman whose head leaves her body at night, floating off with glowing entrails trailing below to feed on filth and fresh blood. It returns to the body before dawn."],
  krahang:["กระหัง ผีผู้ชายคู่กับกระสือ ใช้กระด้งฝัดข้าวเป็นปีกและสากตำข้าวเป็นขาเทียม บินออกหากินกลางคืนและโฉบลงทำร้ายคน", "The krahang, the male counterpart of the krasue, who uses rice-winnowing baskets as wings and a rice pestle as an extra leg to fly out at night and swoop on people."],
  phipop:["ผีปอบ ผีที่สิงในร่างคนเพราะเล่นของผิดครู ชอบกินตับไตคนจนเหยื่อผอมแห้งตาย ตามความเชื่ออีสานต้องให้หมอธรรมมาไล่", "The phi pop of Isan belief, a spirit that possesses someone who misused black magic, eating the liver and kidneys of victims until they waste away. Only a dharma exorcist can drive it out."],
  skelsoldier:["โครงกระดูกทหารที่ถูกฝังรวมไว้ในป่าช้าหลังสงคราม ยังสวมหมวกและถือดาบเก่า เดินแถวทุกคืนเหมือนรอคำสั่งที่ไม่เคยมา", "The bones of soldiers buried together after an old war, still in their caps and gripping rusted swords. They march in file every night as if waiting for orders that never come."],
  omencrow:["อีกาป่าปากหนา คนไทยถือว่าเป็นลางร้าย ถ้าบินเข้าบ้านหรือร้องหน้าบ้านจะมีเรื่องไม่ดี กาจริงฉลาดมาก จำหน้าคนได้และบอกต่อกันในฝูง", "The large-billed crow, a bad omen in Thai belief if it flies into the house or caws at the door. Real crows are very clever: they remember faces and tell the rest of the flock."],
  vengefulshade:["ผีโหงพราย วิญญาณคนตายโหง เช่นถูกฆ่าหรือตายทั้งกลม จึงดุร้ายที่สุดในบรรดาผีไทย หมอผีบางคนเลี้ยงไว้ใช้งาน ถ้าเลี้ยงไม่ดีมันจะย้อนกลับมาทำร้ายเจ้าของ", "A phi tai hong, the spirit of someone who died violently, by murder or in childbirth, the fiercest of Thai ghosts. Some sorcerers keep one as a servant, and if neglected it turns on its master."],
  hauntedurn:["ไหทองคำที่ฝังไว้ใต้ดิน มีผีปู่โสมเฝ้าทรัพย์ตามความเชื่อไทย ผู้ฝังทรัพย์บางคนสาบานให้วิญญาณเฝ้าไว้จนกว่าเจ้าของตัวจริงจะมาขุด ไหนี้จึงไม่ยอมให้ใครแตะ", "An urn of buried gold watched over by a pu som, the treasure-guarding ghost of Thai lore; some who buried wealth bound a spirit to it until the rightful heir came to dig. So the urn lets nobody touch it."],
  /* ---------- 9 The Weeping Plains ---------- */
  banteng:["วัวแดง วัวป่าที่ตัวเมียสีน้ำตาลแดงและตัวผู้สีเข้มเกือบดำ ทุกตัวมีขาท่อนล่างขาวเหมือนสวมถุงเท้าและก้นขาว ทนแล้งได้ดี หากินในทุ่งหญ้าโปร่งเป็นฝูง", "The banteng, a wild cattle whose cows are chestnut and bulls nearly black, all with white 'stockings' and a white rump. Hardy in drought, it grazes open grassland in herds."],
  vulture:["พญาแร้ง แร้งหัวแดงที่เคยพบทั่วไทยแต่สูญพันธุ์จากธรรมชาติไปแล้ว เหลือแต่โครงการเพาะเลี้ยงที่ห้วยขาแข้ง ตัวดำ หัวและคอเปลือยสีแดงเพื่อไม่ให้เลือดติดขนเวลากินซาก", "The red-headed vulture, once seen all over Thailand but now extinct in the wild there, kept alive by a breeding programme at Huai Kha Khaeng. Black with a bare red head and neck so blood will not foul the feathers as it feeds."],
  kingcobra:["งูจงอาง งูพิษที่ยาวที่สุดในโลก ยาวได้ถึงห้าเมตร สีเขียวมะกอกมีลายปล้องสีเหลืองซีด ยกตัวสูงได้หนึ่งในสามของความยาว กินงูอื่นเป็นอาหาร และเป็นงูชนิดเดียวที่ทำรังกกไข่", "The king cobra, the longest venomous snake in the world at up to five metres: olive with pale yellow bands. It rears a third of its length off the ground, eats other snakes, and is the only snake that builds a nest for its eggs."],
  sandscorpion:["แมงป่องสีเหลืองซีดแบบแมงป่องทะเลทราย ตัวผอม ก้ามเล็กแต่หางหนาและพิษแรงกว่าแมงป่องช้าง ซ่อนใต้ดินกลางวันแล้วออกล่ากลางคืน", "A pale yellow scorpion like the desert kinds: slim with small pincers but a thick tail and venom far stronger than the forest scorpion's. It hides underground by day and hunts at night."],
  dustdevil:["ลมหมุนฝุ่นที่เกิดเมื่อพื้นดินร้อนจัดดันอากาศขึ้นเป็นเกลียว ทุ่งกุลาร้องไห้มีให้เห็นบ่อยหน้าแล้ง ชาวบ้านเรียกลมผีหัวกุด ตัวนี้มีดวงตาและวิ่งไล่ชนคนเป็นสาย", "A whirlwind of dust that forms when baking ground pushes air up in a spiral, common on the plains of Kula Ronghai in the dry season. Villagers call it a headless ghost's wind; this one has eyes and chases people down."],
  isanscarecrow:["หุ่นไล่กาอีสานที่ชาวนาผูกผ้าขาวม้าบนหัวและใส่เสื้อเก่าให้ เฝ้าทุ่งมาหลายฤดูแล้ง จนลมร้อนพัดวิญญาณเข้าสิง มันโกรธทุกคนที่เหยียบนาที่มันดูแล", "A scarecrow of Isan with a pakoma cloth wound round its head and an old shirt, left out through so many dry seasons that the hot wind blew a spirit into it. It hates anyone who sets foot in its field."],
  /* ---------- 10 Ancient Khmer Sanctuary ---------- */
  stonenaga:["นาคเจ็ดเศียรจำหลักหินทรายบนราวสะพานนาคของปราสาทขอม เช่นที่พนมรุ้ง นาคเป็นสะพานเชื่อมโลกมนุษย์กับสวรรค์ ตาหินเรืองแสงเมื่อผู้บุกรุกข้ามสะพาน", "A seven-headed naga carved in sandstone along the naga-bridge balustrade of a Khmer sanctuary, as at Phanom Rung. The naga is the rainbow bridge from the human world to heaven, and its stone eyes light up when trespassers cross."],
  khmerlion:["สิงห์ขอมจำหลักหินทรายสีชมพูแบบปราสาทบันทายศรี นั่งหลังตรง แผงคอเป็นลอนขด ตั้งเป็นคู่เฝ้าบันไดทางขึ้นปราสาท", "A Khmer lion carved in pink sandstone in the style of Banteay Srei, sitting bolt upright with a mane of tight curls. Pairs of them guard the stairways up to the sanctuary."],
  stoneapsara:["นางอัปสราที่จำหลักบนผนังปราสาท ในตำนานเกิดจากฟองน้ำตอนกวนเกษียรสมุทร เป็นนางฟ้าผู้ร่ายรำให้เทพ เมื่อร่ายรำแสงศักดิ์สิทธิ์ก็พุ่งออกจากศิลา", "An apsara carved on the sanctuary wall. Legend says the apsaras rose from the foam when the gods churned the Ocean of Milk, celestial dancers for the devas, and when she dances holy light bursts from the stone."],
  khmerghost:["หมาจิ้งจอกทองที่ทำรังในซอกปราสาทหินร้าง ออกหากินตอนโพล้เพล้เป็นคู่หรือฝูงเล็ก เสียงหอนของมันก้องไปตามระเบียงหิน ชาวบ้านเลยเคยเชื่อว่าเป็นวิญญาณทหารขอม", "Golden jackals that den in the cracks of the ruined sanctuary and hunt at dusk in pairs or small packs. Their howls echo down the stone galleries, which is why villagers once took them for the ghosts of Khmer soldiers."],
  carvedmonkey:["ลิงจำหลักหินจากภาพรามายณะบนทับหลัง เป็นทหารวานรของพระราม หินที่ร้าวทำให้วิญญาณวานรหลุดออกมาเล่นซนบนกำแพงปราสาท", "A carved stone monkey from a Ramayana scene on a lintel, one of Rama's monkey soldiers. A crack in the stone let the monkey's spirit out to scamper along the sanctuary walls."],
  sanctuarybat:["ค้างคาวมงกุฎที่อาศัยในปรางค์มืด จมูกมีแผ่นหนังรูปเกือกม้าใช้บังคับทิศคลื่นเสียง ออกล่าแมลงตอนพลบค่ำเป็นสายยาวจากช่องหน้าต่างปรางค์", "A horseshoe bat roosting in the dark of the prang, its horseshoe-shaped noseleaf steering its sonar. At dusk the colony streams out of the prang windows to hunt insects."],
  /* ---------- 11 Andaman Coast ---------- */
  ghostcrab:["ปูลม ปูทรายที่วิ่งเร็วที่สุดชนิดหนึ่งในโลก ตาบนก้านยาวมีติ่งคล้ายเขา ตัวสีทรายจนแทบมองไม่เห็นบนหาด ขุดรูลึกและออกหากินตอนกลางคืน", "The horned ghost crab, one of the fastest-running crabs on earth, with tall eyestalks ending in little horns and a body so sand-coloured it vanishes on the beach. It digs deep burrows and comes out at night."],
  hermitcrab:["ปูเสฉวน ท้องนิ่มต้องอาศัยเปลือกหอยเปล่าเป็นบ้าน และต้องย้ายบ้านใหม่ทุกครั้งที่ตัวโตขึ้น ตัวนี้โตจนต้องใช้เปลือกหอยสังข์ยักษ์และป้องกันบ้านด้วยชีวิต", "A hermit crab, whose soft belly must live inside an empty seashell that it trades up every time it grows. This one is so big it took a giant conch, and it will defend that home with its life."],
  leatherback:["เต่ามะเฟือง เต่าทะเลที่ใหญ่ที่สุดในโลก กระดองไม่ใช่เกล็ดแข็งแต่เป็นหนังดำมีจุดขาวและสันนูนเจ็ดสันตามยาวเหมือนผลมะเฟือง ดำน้ำได้ลึกกว่าพันเมตรและกินแมงกะพรุน ขึ้นวางไข่ที่หาดพังงาและภูเก็ต", "The leatherback, the largest sea turtle on earth: its shell is not hard plates but black leathery skin with white spots and seven lengthwise ridges like a star fruit. It dives deeper than a thousand metres, eats jellyfish and nests on the beaches of Phang Nga and Phuket."],
  pirategull:["นกนางนวลที่โฉบแย่งอาหารจากมือนักท่องเที่ยวและขโมยปลาจากนกตัวอื่นกลางอากาศ พฤติกรรมเดียวกับนกสกัวที่เรียกกันว่านกโจรสลัด", "A gull that dives to snatch food from tourists' hands and steals fish from other birds in mid-air, the same piracy that skuas are known for."],
  seakrait:["งูสมิงทะเลปากเหลือง ลายปล้องดำสลับฟ้าเทา หางแบนเป็นใบพาย พิษแรงกว่างูเห่าหลายเท่าแต่นิสัยเชื่อง ขึ้นบกมาวางไข่และย่อยอาหารบนโขดหิน ตัวที่นี่ไม่เชื่องแล้ว", "The yellow-lipped sea krait, banded black and blue-grey with a paddle-flat tail. Its venom is many times stronger than a cobra's though it is usually gentle, and it comes ashore to lay eggs and digest on the rocks. These ones are no longer gentle."],
  walkcoral:["ปะการังเขากวางที่ฟอกขาวแล้วฟื้นขึ้นมาเป็นสัตว์เดินได้ ปะการังจริงเป็นสัตว์ตัวเล็กนับล้านที่อยู่ร่วมกับสาหร่าย เมื่อน้ำร้อนเกินไปสาหร่ายหนีออกจนปะการังซีด", "A staghorn coral that bleached and then rose up walking. Real coral is millions of tiny animals living with algae; when the sea gets too warm the algae leave and the coral turns white."],
  firejelly:["แมงกะพรุนไฟ หนวดยาวมีเข็มพิษนับพันที่ยิงออกเมื่อสัมผัส ทำให้ผิวแสบร้อนเหมือนถูกไฟ ชาวประมงใช้น้ำส้มสายชูราดแผล ลอยมากับคลื่นหน้ามรสุม", "A sea-nettle jellyfish whose long tentacles fire thousands of venomous stinging cells on contact, burning like fire; fishermen pour vinegar on the wound. It drifts in on the monsoon swells."],
  /* ---------- 12 Sea-Ogress Isle ---------- */
  lostmermaid:["นางเงือกในพระอภัยมณีของสุนทรภู่ที่ช่วยพาพระอภัยหนีจากนางผีเสื้อสมุทร ตนนี้พลัดจากฝูงเพราะพายุ จึงหวาดระแวงทุกคนที่เข้าใกล้เกาะ", "A mermaid from Sunthorn Phu's epic Phra Aphai Mani, of the kind that helped Phra Aphai flee the Sea Ogress. This one lost her shoal in a storm and now fears anyone who nears the island."],
  maninmangkon:["ม้านิลมังกร พาหนะของสุดสาครในพระอภัยมณี หัวเป็นมังกร ตัวเป็นม้าสีดำนิล มีเกล็ด วิ่งบนผิวน้ำได้ ตัวป่าบนเกาะนี้ยังไม่มีใครปราบให้เชื่องได้", "The Ma Nin Mangkon, steed of Sud Sakhon in Phra Aphai Mani: a dragon-headed, jet-black scaled horse that gallops on water. The wild ones on this island have never been tamed."],
  giantclam:["หอยมือเสือ หอยสองฝาที่ใหญ่ที่สุดในโลก ขอบปากหอยมีสาหร่ายอาศัยจึงมีสีเขียวฟ้าสด อายุยืนกว่าร้อยปี เมื่อตกใจจะหุบฝาช้า ๆ ไม่ได้งับคนอย่างที่เล่ากัน แต่ตัวนี้งับจริง", "The giant clam, the largest bivalve on earth, its mantle bright blue-green from the algae living in it, and it can live past a hundred. Real clams close slowly and do not trap divers as tales say; this one does."],
  giantsquid:["หมึกยักษ์จากทะเลลึก ตาใหญ่ที่สุดในอาณาจักรสัตว์ หนวดยาวมีปุ่มดูดขอบหยัก เมื่อถูกไล่จะพ่นหมึกดำบังตาแล้วหนี ตัวนี้ขึ้นมาล่าเรือประมงตอนกลางคืน", "A squid from the deep sea with the largest eyes in the animal kingdom and long arms ringed with toothed suckers. Chased, it squirts black ink and flees; this one rises at night to hunt fishing boats."],
  seawraith:["วิญญาณกะลาสีเรือที่จมทะเล ผมพันสาหร่ายทะเล ชาวประมงอันดามันเชื่อว่าคืนเดือนมืดจะมีผีพรายทะเลเกาะท้ายเรือ ต้องโปรยข้าวสารก่อนออกเรือ", "The ghost of a drowned sailor with sea-grass tangled in its hair. Andaman fishermen say sea phrai cling to boat sterns on dark nights, and scatter rice before they put to sea."],
  seaserpent:["งูทะเลยักษ์ในนิทานกะลาสีที่ยาวพอจะรัดเรือ เชื่อกันว่าเรื่องเล่านี้มาจากการเห็นปลาออร์ฟิชหรือฝูงโลมาว่ายเป็นแถว ตัวนี้มีจริงและเป็นสัตว์เลี้ยงของนางผีเสื้อสมุทร", "The sea serpent of sailors' yarns, long enough to crush a boat. The tales probably come from oarfish or dolphins swimming in a line; this one is real, and the Sea Ogress keeps it as a pet."],
  /* ---------- 13 Ruins of Ayodhya ---------- */
  ghosthorse:["ม้าศึกในกองทัพอยุธยาที่ตายพร้อมนายเมื่อกรุงแตกปี พ.ศ. 2310 ยังห้อตะบึงไปมาตามซากกำแพงเมือง ดวงตาเรืองแสงสีฟ้าซีด", "A warhorse of the Ayutthaya army that fell with its rider when the city was sacked in 1767, still galloping along the ruined walls with pale blue glowing eyes."],
  ghostelephant:["ช้างศึกผีที่เคยออกรบในสงครามยุทธหัตถี ช้างศึกจริงฝึกให้ใช้งาแทงและเท้าเหยียบข้าศึก วิญญาณมันยังจำเสียงฆ้องกลองได้และพุ่งเข้าหาเสียงนั้น", "A ghost war elephant from the age of elephant duels. Real war elephants were trained to gore with their tusks and trample, and this one still remembers the gongs and drums and charges at the sound."],
  ayutsoldier:["ทหารผีอยุธยาสวมเสื้อแดงแบบไพร่พลในจิตรกรรมฝาผนัง ยังถือดาบเฝ้าประตูเมือง ไม่รู้ว่ากรุงแตกไปนานแล้ว", "An Ayutthaya ghost soldier in the red tunic of troops in the old temple murals, still guarding the city gate with his sword, unaware the city fell long ago."],
  celadonjar:["ไหเคลือบศิลาดลจากเตาสังคโลกและเตาจีน สินค้าส่งออกล้ำค่าของอยุธยา ไหใบนี้ใช้ฝังทรัพย์ก่อนกรุงแตก คำสาปของเจ้าของยังเย็นจนเป็นน้ำแข็ง", "A celadon jar from the Sangkhalok and Chinese kilns, one of Ayutthaya's prized exports. It was used to bury treasure before the city fell, and its owner's curse is still cold enough to freeze."],
  whiteraven:["กาเผือก กาที่ขาดเม็ดสีจึงขาวทั้งตัวและตาแดง พบได้ยากมาก คนโบราณถือว่าเป็นสัตว์มงคลคู่บารมีกษัตริย์ ตัวนี้เฝ้ากรุสมบัติอยู่ในเจดีย์ร้าง", "A white crow, an albino lacking pigment, white all over with pink-red eyes and extremely rare; the ancients counted one an auspicious sign of a king's merit. This one guards the relic crypt in a ruined chedi."],
  treasurespirit:["ผีเฝ้าทรัพย์ในกรุเจดีย์ ตามความเชื่อการบรรจุกรุ ของมีค่าและพระพิมพ์ถูกฝังพร้อมคำสาปให้วิญญาณคุ้มครอง ใครลักลอบขุดกรุจะถูกตามทำร้าย", "A spirit bound to guard a chedi crypt. Old custom sealed valuables and votive tablets inside with a curse that set a spirit to protect them, and crypt robbers are hunted down."],
  vaultpython:["งูเหลือม งูที่ยาวที่สุดในโลก ยาวได้เกินหกเมตร ไม่มีพิษแต่รัดเหยื่อจนหยุดหายใจ ลายตาข่ายบนตัวช่วยพรางตัวในป่า ตัวนี้อาศัยในกรุใต้เจดีย์มานานจนตัวโตผิดปกติ", "The reticulated python, the longest snake in the world at over six metres. It has no venom but constricts prey until it stops breathing, its net pattern hiding it in the forest. This one has lived in the crypt under the chedi so long it has grown monstrous."],
  /* ---------- 14 Outer Himmapan ---------- */
  kilen:["กิเลน สัตว์มงคลที่ไทยรับมาจากคติจีน ฉีหลิน หัวคล้ายมังกร ตัวมีเกล็ด กีบเหมือนกวาง ว่ากันว่าปรากฏตัวเฉพาะในยุคที่มีผู้ปกครองทรงธรรม และพ่นไฟใส่ผู้ไม่ชอบธรรม", "The kilen, a lucky beast Thailand took from the Chinese qilin: a dragon-like head, a scaly body and deer's hooves. It is said to appear only under a just ruler, and breathes fire on the unjust."],
  kotchasi:["คชสีห์ สัตว์หิมพานต์หัวเป็นช้าง ตัวเป็นราชสีห์ รวมพลังช้างกับความกล้าของสิงห์ เป็นตราประจำตำแหน่งสมุหกลาโหมในสมัยอยุธยา", "The kotchasi, a Himmapan beast with an elephant's head on a lion's body, joining the elephant's strength to the lion's courage. It was the seal of the Minister of the Military in the Ayutthaya era."],
  karawek:["นกการเวก นกในวรรณคดีที่มีเสียงไพเราะที่สุดในป่าหิมพานต์ กล่าวกันว่าเมื่อมันร้องสัตว์ทั้งป่าจะหยุดฟังจนลืมกิน เสียงร้องของมันกลายเป็นแสงศักดิ์สิทธิ์", "The karawek, the bird of Thai literature with the sweetest voice in Himmapan; when it sings, they say, every creature stops to listen and forgets to eat. Its song becomes holy light."],
  wingedhorse:["ม้าปีกในวรรณคดีไทย เช่นม้าที่พาเจ้าชายเหาะข้ามป่าหิมพานต์ ขนขาวบริสุทธิ์ บินได้เร็วกว่าลม ไม่ยอมให้ใครขี่นอกจากผู้มีบุญ", "The winged horse of Thai tales, which carries princes across the Himmapan forest: pure white and faster than the wind, letting nobody ride it but the truly meritorious."],
  goldsingha:["สิงห์ทอง ราชสีห์หิมพานต์ที่ขนเป็นสีทองทั้งตัว ในวรรณคดีราชสีห์เป็นเจ้าแห่งป่าที่เพียงคำรามสัตว์อื่นก็ขวัญหนี ออกล่าเฉพาะสัตว์ที่ท้าทายมัน", "A golden singha, a Himmapan lion golden from mane to tail. In the old poems the lion is lord of the forest whose roar alone scatters other beasts, and it hunts only those that challenge it."],
  kinnorn:["กินนร ครึ่งคนครึ่งนก ท่อนบนเป็นชายหนุ่ม ท่อนล่างและหางเป็นนก บินได้ อาศัยที่เขาไกรลาส เก่งการดนตรีและยิงธนู คู่กับกินรีในวรรณคดีพระสุธน", "A kinnorn, half man and half bird, a youth above with a bird's legs and tail below, who flies and lives on Mount Kailash. Masters of music and archery, they are the male kin of the kinnaree in the tale of Prince Suthon."],
  /* ---------- 15 Lake Anodat ---------- */
  goldhamsa:["หงส์ สัตว์ในคติพราหมณ์เป็นพาหนะของพระพรหม ชาวมอญและพม่าใช้เป็นสัญลักษณ์เมืองหงสาวดี ว่ากันว่าแยกน้ำนมออกจากน้ำได้ อาศัยอยู่ที่สระอโนดาต", "The hamsa, in Brahmin lore the mount of Brahma, and the emblem of the Mon city of Hongsawadi. It is said to separate milk from water, and it nests on Lake Anodat."],
  matchanu:["มัจฉานุ ลูกของหนุมานกับนางสุพรรณมัจฉาในรามเกียรติ์ ตัวเป็นวานรขาว หางเป็นปลา ได้รับมอบหมายจากไมยราพให้เฝ้าด่านทางน้ำ", "Matchanu, son of Hanuman and the mermaid Suphanmatcha in the Ramakien: a white monkey with a fish's tail, set by Maiyarap to guard the water gate."],
  lakenaga:["นาคน้อยที่เกิดในสระอโนดาต ตามคติไตรภูมิ สระนี้อยู่ในป่าหิมพานต์และเป็นต้นแม่น้ำใหญ่ทั้งห้า นาคหนุ่มยังไม่มีหงอนเต็มที่จึงเฝ้าสระอย่างระแวดระวัง", "A young naga hatched in Lake Anodat, which in the Traiphum cosmology lies in Himmapan and feeds the five great rivers. Too young for a full crest, it guards the lake warily."],
  skylotus:["บัวสวรรค์ดอกขาวบริสุทธิ์ ในพุทธประวัติเมื่อพระโพธิสัตว์ประสูติก้าวเดินเจ็ดก้าวมีดอกบัวผุดรองรับ บัวในสระอโนดาตจึงมีชีวิตและเดินได้", "A pure white celestial lotus. In the Buddha's life story, lotuses sprang up under each of the seven steps he took at birth, and so the lotuses of Lake Anodat came alive and walk."],
  waterelephant:["วารีกุญชร สัตว์หิมพานต์ครึ่งช้างครึ่งปลา ท่อนหน้าเป็นช้าง ท่อนหลังเป็นหางปลา ว่ายอยู่ในสระอโนดาตและท้องทะเล พ่นน้ำจากงวงได้แรงเหมือนน้ำตก", "The wari kunchon, a Himmapan beast with an elephant's front and a fish's tail, swimming in Lake Anodat and the sea. It sprays water from its trunk as hard as a waterfall."],
  goldshrimp:["กุ้งก้ามกราม กุ้งน้ำจืดตัวใหญ่ที่สุดของไทย ตัวผู้มีก้ามยาวสีฟ้า ชอบซ่อนในซอกหินใต้น้ำ ตัวในสระศักดิ์สิทธิ์นี้เปลือกเหลืองทองด้วยแร่ในน้ำ", "The giant freshwater prawn, Thailand's biggest prawn, whose males carry long blue claws and hide among underwater rocks. In the sacred lake its shell has turned gold from the minerals in the water."],
  /* ---------- 16 Hidden City of Laplae ---------- */
  laplaefolk:["ชาวเมืองลับแล ตำนานจากอุตรดิตถ์เล่าว่าเป็นเมืองที่มองไม่เห็น คนในเมืองห้ามพูดปด ผู้หญิงทอผ้าเก่ง ใครเข้าไปแล้วพูดโกหกจะถูกขับออกและหาทางกลับไม่เจออีก", "A folk of Laplae, the invisible city of Uttaradit legend, where nobody may tell a lie and the women are fine weavers. A visitor who lies is cast out and can never find the way back."],
  spiritkoel:["นกกาเหว่า ตัวผู้ดำเหลือบ ตาแดง ร้องเสียงดังว่าเหว่า ๆ ไม่เลี้ยงลูกเองแต่วางไข่ในรังกา ชาวบ้านเชื่อว่าเสียงร้องยามค่ำเป็นการส่งข่าวจากวิญญาณ", "The Asian koel: the male glossy black with red eyes and a loud ko-el call. It lays its eggs in crows' nests and never raises its own young, and villagers say its night calls carry messages from the dead."],
  misttiger:["เสือโคร่งที่อาศัยในหมอกจนขนจางเป็นสีเทา เสือโคร่งจริงลายไม่ซ้ำกันเลยสักตัวเหมือนลายนิ้วมือ ล่าแบบซุ่มจากด้านหลัง ตัวนี้หายเข้าไปในหมอกได้ทั้งตัว", "A tiger that has lived in the fog so long its coat has faded grey. Real tigers' stripes are unique to each animal like fingerprints, and they ambush from behind; this one can vanish into the mist entirely."],
  wanderdurian:["ทุเรียนหมอนทอง ราชาผลไม้ที่ลับแลขึ้นชื่อเรื่องทุเรียนหลงลับแลและหลินลับแล เปลือกหนามแหลม กลิ่นแรงจนบางประเทศห้ามนำขึ้นรถสาธารณะ ลูกนี้สุกจนตกจากต้นแล้วกลิ้งเดินเอง", "A durian, king of fruits; Laplae is famous for its Long Laplae and Lin Laplae varieties. Its husk is all spikes and its smell is so strong some countries ban it on public transport. This one ripened, fell and rolled off on its own."],
  woodsentinel:["หุ่นไม้สักแกะสลักที่ชาวลับแลตั้งไว้เฝ้าประตูเมือง ไม้สักทนปลวกและความชื้นได้นับร้อยปี หุ่นนี้ยังยืนเฝ้าและไล่คนพูดเท็จออกไป", "A carved teak figure the people of Laplae set at their city gate. Teak resists termites and damp for centuries, and the sentinel still stands, driving out anyone who lies."],
  laplaemist:["ม่านหมอกที่ซ่อนเมืองลับแลไว้จากสายตาคนนอก กลายร่างเป็นเงาคลุมผ้าห่อศพเพื่อขับไล่ผู้บุกรุก หากใครหลงเข้าไปจะลืมทางกลับบ้าน", "The veil of mist that hides Laplae from outsiders, taking the form of a shrouded shade to drive intruders off. Whoever strays inside forgets the way home."],
  /* ---------- 17 Naga Underworld ---------- */
  nagaretainer:["นาคบริวารในเมืองบาดาล ตามความเชื่อลุ่มน้ำโขง พญานาคมีบริวารนับหมื่น ตัวนี้มีหงอนแต่ไม่มีมงกุฎเพราะไม่ได้มีเชื้อพระวงศ์ คอยลาดตระเวนตามถนนแก้วมรกต", "A naga retainer of the underworld city. Mekong belief says each naga king commands tens of thousands of servants; this one wears a crest but no crown, being of no royal line, and patrols the emerald streets."],
  nagawarrior:["ทหารนาคาที่แปลงกายเป็นครึ่งคนครึ่งงู ตามตำนานนาคแปลงร่างเป็นคนขึ้นมาบนโลกมนุษย์ได้ ทหารพวกนี้ถือดาบเฝ้าประตูเมืองบาดาล", "A naga soldier in half-human form. Legend says nagas can take human shape to walk the upper world; these warriors carry swords to guard the gates of the underworld."],
  abyssjelly:["แมงกะพรุนน้ำลึกที่เรืองแสงสีฟ้าเขียวด้วยตัวเอง สัตว์ทะเลลึกส่วนใหญ่ผลิตแสงได้ ไว้ล่อเหยื่อหรือหลอกผู้ล่า มันลอยเป็นโคมไฟให้เมืองบาดาล", "A deep-sea jellyfish that glows blue-green with its own light; most deep-sea animals make light, to lure prey or confuse predators. These ones drift like street lamps through the underworld city."],
  emeraldcrab:["ปูที่กินผลึกแร่ในเมืองบาดาลจนกระดองเป็นสีมรกต ปูทุกชนิดต้องลอกคราบเพื่อโต และช่วงลอกคราบใหม่จะเปราะบางที่สุด ตัวนี้จึงดุร้ายเป็นพิเศษ", "A crab that eats the crystal of the underworld until its shell turns emerald. Every crab must moult to grow and is weakest right after, so this one is especially vicious."],
  thundereel:["ปลาไหลไฟฟ้าที่สร้างไฟฟ้าได้หลายร้อยโวลต์จากเซลล์พิเศษในลำตัว ใช้ช็อตเหยื่อและป้องกันตัว ปลาไหลไฟฟ้าจริงไม่ใช่ปลาไหลแต่เป็นญาติกับปลากราย", "An electric eel that generates hundreds of volts from special cells in its body to stun prey and defend itself. Real electric eels are not true eels but relatives of the knifefish."],
  spiritpearl:["ไข่มุกที่หอยมุกสร้างขึ้นเมื่อมีสิ่งแปลกปลอมเข้าไป โดยเคลือบชั้นมุกทับทีละชั้นนานหลายปี ไข่มุกนี้อยู่ในคลังพญานาคจนดูดวิญญาณไว้ข้างใน และยิงแสงใส่ผู้บุกรุก", "A pearl, formed when a pearl oyster coats an intruding grain in nacre layer by layer over years. This one sat in the naga king's treasury until it took in a spirit, and it shoots light at intruders."],
  abyssturtle:["เต่าที่อยู่ในเมืองบาดาลมาหลายร้อยปี เต่าบางชนิดอายุยืนกว่าคน กระดองมีผลึกเรืองแสงงอกตามรอยต่อ เชื่อกันว่าเป็นพาหนะของนาคชั้นสูง", "A turtle that has lived in the underworld for centuries; some tortoises really do outlive humans. Glowing crystals grow along the seams of its shell, and it is said to carry high-ranking nagas."],
  /* (v294) วังบาดาล: the sea creatures of the drowned palace */
  abyssshark:["ฉลามที่ลาดตระเวนรอบวังบาดาลไม่เคยหยุด ฉลามจริงต้องว่ายน้ำตลอดเวลาเพื่อให้น้ำไหลผ่านเหงือก และรับรู้ไฟฟ้าอ่อน ๆ จากหัวใจเหยื่อได้", "A shark that circles the drowned palace without rest. Real sharks must keep swimming so water flows over their gills, and they sense the faint electric pulse of a beating heart."],
  mantaray:["ปลากระเบนราหูตัวกว้างเท่าเรือ กระพือครีบเหมือนบินอยู่ในน้ำ กระเบนราหูจริงกินแพลงก์ตอน และเป็นปลาที่มีสมองใหญ่ที่สุดเมื่อเทียบกับขนาดตัว", "A manta as wide as a boat that flies through the water on slow wingbeats. Real mantas eat plankton and have the largest brain for their size of any fish."],
  giantpuffer:["ปลาปักเป้าที่พองตัวเป็นลูกหนามเมื่อตกใจ ปลาปักเป้าจริงสูบน้ำเข้าท้องจนกลมเป็นลูกบอล และเนื้อบางส่วนมีพิษร้ายแรงกว่าไซยาไนด์หลายเท่า", "A pufferfish that swells into a spiked ball when alarmed. Real puffers gulp water until they are round, and some of their organs hold a poison far deadlier than cyanide."],
  abyssangler:["ปลาตกเบ็ดที่ห้อยดวงไฟไว้หน้าปากในความมืดของห้วงลึก ปลาตกเบ็ดจริงใช้แบคทีเรียเรืองแสงในเหยื่อล่อ และกลืนเหยื่อที่ใหญ่กว่าตัวมันได้", "An anglerfish that dangles a lamp before its jaws in the deep dark. Real anglerfish keep glowing bacteria in their lure and can swallow prey larger than themselves."],
  seahorseknight:["ม้าน้ำที่ยืนเฝ้าประตูวังเป็นแถวเหมือนทหารองครักษ์ ม้าน้ำจริงเป็นปลาที่ตัวผู้ตั้งท้องแทนตัวเมีย และใช้หางม้วนเกาะสาหร่ายไว้ไม่ให้ลอยไป", "Seahorses that stand in rows at the palace gate like a royal guard. In real seahorses the father carries the eggs, and the curled tail grips seaweed so the current cannot carry them off."],
  lionfish:["ปลาสิงโตที่กางครีบลายแดงขาวเหมือนแผงคอสิงห์ ก้านครีบแหลมของปลาสิงโตจริงมีพิษ ใครโดนตำจะปวดบวมอยู่หลายวัน สีสดของมันจึงเป็นคำเตือน", "A lionfish that spreads its red and white fins like a lion's mane. The spines of real lionfish carry venom that leaves a sting swollen for days, so its bright colours are a warning."],
  swordfish:["ปลากระโทงดาบที่พุ่งเข้าใส่ด้วยปากแหลมยาวเหมือนดาบ ปลากระโทงดาบจริงว่ายได้เร็วมาก และอุ่นดวงตากับสมองให้มองเห็นชัดในน้ำลึกที่เย็นเฉียบ", "A swordfish that charges with a bill as long as a blade. Real swordfish are among the fastest swimmers and warm their own eyes and brain to see clearly in cold deep water."],
  abyssoctopus:["ปลาหมึกยักษ์ที่คลืบคลานบนพื้นทรายด้วยแปดหนวด ปลาหมึกยักษ์จริงมีหัวใจสามดวง เลือดสีฟ้า และเปลี่ยนสีผิวให้กลืนกับหินได้ในพริบตา", "A giant octopus that crawls over the sand on eight arms. Real octopuses have three hearts and blue blood, and can change the colour of their skin to match the rocks in a blink."],
  armorlobster:["กุ้งมังกรที่เปลือกแข็งเหมือนเกราะทหารวังบาดาล กุ้งมังกรจริงลอกคราบเพื่อโตขึ้น และใช้ก้ามข้างใหญ่บดเปลือกหอย ส่วนก้ามข้างเล็กใช้ฉีกเนื้อ", "A lobster whose shell is as hard as the armour of the palace guard. Real lobsters moult to grow, crushing shells with the big claw and tearing food with the smaller one."],
  /* ---------- 18 Inner Himmapan ---------- */
  thaktho:["ทักทอ สัตว์หิมพานต์ที่ผสมช้างกับสิงห์อีกรูปแบบหนึ่ง ตัวเป็นช้างมีเขา งาโค้ง ในภาพจิตรกรรมมักมีสีคล้ำ ดุร้ายและหวงถิ่นอย่างยิ่ง", "The thak tho, another elephant-lion of Himmapan: an elephant body with horns and curved tusks, usually painted in dark tones in temple murals. It is fierce and fiercely territorial."],
  kraisorn:["ไกรสรราชสีห์ ราชสีห์ที่สูงศักดิ์ที่สุดในสี่จำพวกตามคัมภีร์ ตัวขาว ปาก หาง และเท้าแดง กินเนื้อเป็นอาหาร ตัวนี้แปลงร่างได้ จึงเรียกไกรสรจำแลง", "The kraisorn, highest of the four kinds of singha in the old texts: white with red mouth, tail and feet, and a meat eater. This one can change its shape, hence its name."],
  sakuna:["สกุณไกรสร สัตว์หิมพานต์หัวเป็นนก ตัวเป็นราชสีห์ มีสร้อยคอเป็นแผงขนเหมือนแผงคอสิงห์ บินโฉบลงมาพ่นไฟใส่เหยื่อ", "The sakuna kraisorn, a Himmapan beast with a bird's head on a lion's body and a ruff of feathers like a lion's mane. It swoops down and breathes fire on its prey."],
  asurabird:["อสูรปักษา นกในป่าชั้นในที่เป็นบริวารของอสูร ขนดำแดง ตาแดงก่ำ กรงเล็บงุ้มคมเหมือนมีด บินไล่ผู้ที่เข้าใกล้ถิ่นอสูร", "The asura paksa, a bird of the inner forest that serves the asuras: black and blood-red plumage, glowing red eyes and hooked talons sharp as knives. It harries anyone near asura land."],
  himogre:["ยักษ์ป่าหิมพานต์ ยักษ์ในคติไทยเป็นเผ่าที่มีฤทธิ์มาก เขี้ยวงอก ผิวกายหลายสี สวมชฎายอด ชอบอยู่ในป่าลึกและกินคนที่หลงเข้ามา", "A yaksha of the Himmapan forest; in Thai lore the yak are a mighty race with jutting fangs, skin of many colours and spired crowns. It keeps to the deep forest and eats travellers who stray in."],
  hemaraj:["เหมราช สัตว์หิมพานต์ผสมระหว่างหงส์กับราชสีห์ ตัวเป็นสิงห์สีทอง มีปีกหงส์ งามสง่าและหายากยิ่งในป่าชั้นใน", "The hemaraj, a Himmapan blend of hamsa and lion: a golden lion with the wings of a swan, regal and extremely rare in the inner forest."],
  wingednaga:["นาคปักษิณ นาคมีปีกตามคติหิมพานต์ เกล็ดสีม่วง ปีกขนนก เหาะได้ทั้งในน้ำและบนฟ้า ฟาดฟ้าผ่าลงจากเมฆ", "A winged naga of Himmapan with violet scales and feathered wings, as at home in water as in the sky. It calls lightning down from the clouds."],
  /* ---------- 19 Mount Kailash ---------- */
  snowsingha:["สิงห์ประจำเขาไกรลาส ที่ประทับของพระอิศวรในคติพราหมณ์ ขนขาวดั่งหิมะ แผงคอฟ้าอ่อน ตาเรืองแสงเย็นเยียบ เฝ้าทางขึ้นเขาศักดิ์สิทธิ์", "The singha of Mount Kailash, home of Shiva in Brahmin belief, white as snow with a pale blue mane and cold glowing eyes. It guards the path up the holy mountain."],
  gandharva:["คนธรรพ์ เทพนักดนตรีแห่งสวรรค์ในคติฮินดูและพุทธ บริวารของท้าวธตรฐ ร่ายมนต์ผ่านบทเพลง แสงศักดิ์สิทธิ์พุ่งตามจังหวะดนตรี", "A gandharva, a celestial musician in Hindu and Buddhist lore and a follower of the guardian king Dhatarattha. It casts spells through song, and holy light flies on the beat."],
  younggaruda:["ครุฑหนุ่มที่ยังไม่ได้รับมงกุฎ ครุฑเป็นพญานกพาหนะของพระนารายณ์และเป็นศัตรูคู่แค้นของนาค ตัวยังเล็กแต่กรงเล็บแข็งแรงพอจะฉีกเกล็ดนาค", "A young garuda not yet crowned. The garuda is the king of birds, mount of Vishnu and sworn enemy of the nagas; small as it is, its talons can already tear naga scales."],
  frostyaksha:["ยักษ์น้ำแข็งที่ตั้งรกรากบนยอดเขาหิมะ ผิวกายฟ้าซีด เขางอกสีขาว เฝ้าทางขึ้นเขาไกรลาสตามคำสั่งท้าวเวสสุวรรณ เจ้าแห่งยักษ์ทั้งปวง", "An ice yaksha settled on the snow peaks, pale blue with white horns, guarding the road up Kailash on the orders of Vessavana, lord of all yakshas."],
  icesentinel:["หินแกรนิตเปลือยบนไหล่เขาที่น้ำแข็งเกาะเป็นผลึกแหลม การแข็งตัวและละลายของน้ำในรอยแตกค่อย ๆ ผ่าหินให้แยก หินก้อนนี้แยกออกมาแล้วลุกขึ้นเฝ้าทาง", "A bare granite boulder on the mountainside bristling with ice crystals. Water freezing and thawing in its cracks slowly splits the rock apart, and this one split off and rose up to guard the path."],
  snowdeva:["วิญญาณเทวดาชั้นล่างที่สถิตบนยอดหิมะ ปรากฏเป็นแสงหน้ากากลอยกลางลมหนาว คอยทดสอบใจผู้แสวงบุญที่ขึ้นเขาศักดิ์สิทธิ์", "The spirit of a lesser deva dwelling on the snowy peaks, seen as a glowing masked light in the icy wind. It tests the hearts of pilgrims who climb the sacred mountain."],
  /* ---------- 20 Mount Meru ---------- */
  guardiandeva:["เทวดาผู้พิทักษ์เขาพระสุเมรุ แต่งกายแบบเทวดาไทยในจิตรกรรมฝาผนัง สวมชฎา กรองศอ และภูษาทอง ไม่มีปีกแต่เหาะได้ด้วยฤทธิ์ ถือพระขรรค์กั้นทางผู้ไม่มีบุญ", "A guardian deva of Mount Meru dressed like the devas of Thai temple murals in a spired chada crown, jewelled collar and gold cloth. Devas have no wings but fly by their power, and this one bars the way to the unworthy with a sword."],
  youngerawan:["ลูกช้างเผือกที่จะเติบโตเป็นช้างเอราวัณ ช้างเผือกตามตำราไม่ได้ขาวจัดแต่สีชมพูอ่อน ตาสีอ่อน เล็บขาว ถือเป็นช้างคู่บารมีกษัตริย์", "A white elephant calf that will grow into an Erawan. By the old treatises a white elephant is not snow white but pale pink with light eyes and white nails, and it is the auspicious companion of kings."],
  goldkinnaree:["กินรีทอง หญิงสาวครึ่งนกที่งามที่สุดในวรรณคดี เช่นนางมโนราห์ในพระสุธน ถอดปีกหางเล่นน้ำในสระได้ ร่ายรำแล้วแสงทองส่องสว่าง", "A golden kinnaree, the half-bird maiden counted most beautiful in Thai literature, like Manohra in the tale of Prince Suthon, who could take off her wings and tail to bathe. When she dances, golden light shines out."],
  celestialsingha:["สิงห์สวรรค์ผู้เฝ้าวิมานบนยอดเขาพระสุเมรุ ขนขาวทองสวมมงกุฎ ตามคติไตรภูมิ สัตว์บนสวรรค์มีกายทิพย์ไม่แก่ไม่ตาย", "A celestial singha guarding the palaces on the summit of Meru, white and gold and crowned. In the Traiphum cosmology heavenly beings have divine bodies that never age or die."],
  goldnaga:["นาคทองสามเศียรผู้เฝ้าเชิงเขาพระสุเมรุ ตามคติไตรภูมิ นาคเป็นหนึ่งในผู้พิทักษ์เขาพระสุเมรุชั้นล่างสุด เกล็ดทองสะท้อนแสงจนตาพร่า", "A three-headed golden naga at the foot of Meru; in the Traiphum the nagas guard the lowest terrace of the world mountain. Its gold scales flash bright enough to blind."],
  asura:["อสูร เผ่าที่เคยอยู่บนดาวดึงส์แต่ถูกพระอินทร์ขับลงไปอยู่ใต้เขาพระสุเมรุ จึงคอยยกทัพขึ้นมาตีสวรรค์ไม่สิ้นสุด ผิวแดง เขี้ยวงอก ดุดันในการรบ", "An asura, of the race that lived in Tavatimsa until Indra cast them down beneath Meru, so they march up to storm heaven without end. Red-skinned, fanged and ferocious in battle."],
  goldgaruda:["ครุฑทองผู้เฝ้าป่าไม้งิ้วบนเขาพระสุเมรุ ตามคติไตรภูมิครุฑอาศัยในวิมานบนต้นงิ้ว สวมมงกุฎ ขนทองกับปีกแดง โฉบลงจับนาคเป็นอาหาร", "A golden garuda of the silk-cotton forest on Meru; in the Traiphum the garudas live in palaces among the simbali trees. Crowned, gold-feathered and red-winged, it swoops down to seize nagas as food."],
  fallenstar:["ดาวตก หรือที่คนไทยเรียกว่าผีพุ่งไต้ คือเศษหินจากอวกาศที่ลุกไหม้เมื่อเสียดสีชั้นบรรยากาศ ดวงนี้ไม่ไหม้หมดแต่ตกลงบนเขาพระสุเมรุและมีวิญญาณ", "A meteor, which Thais call phi phung tai, the torch-bearing ghost: a piece of space rock burning up as it rubs through the air. This one did not burn away but landed on Meru and came alive."],
  /* ---------- 21 Sun-scorched Dunes ---------- */
  sandlizard:["กิ้งก่าทะเลทรายที่วิ่งบนทรายร้อนได้เร็วมาก กิ้งก่าจริงยกขาสลับเพื่อไม่ให้เท้าร้อนเกินไป และมุดลงใต้ทรายเมื่อถูกไล่", "A dune lizard that sprints across burning sand. Real desert lizards lift their feet in turn so they will not overheat, and dive under the sand when chased."],
  dunevulture:["แร้งอียิปต์ ตัวขาว ขนปีกปลายดำ หน้าเปลือยสีเหลือง เป็นนกไม่กี่ชนิดที่ใช้เครื่องมือ โดยคาบหินทุ่มให้ไข่นกกระจอกเทศแตก วนบินเหนือทะเลทรายหาซาก", "The Egyptian vulture: white with black flight feathers and a bare yellow face, one of the few birds that uses tools, dropping stones to crack ostrich eggs. It circles the dunes looking for carrion."],
  sandworm:["หนอนทรายยักษ์ที่มุดใต้ผืนทราย รับรู้แรงสั่นสะเทือนของฝีเท้าแล้วโผล่ขึ้นมางับ ชาวทะเลทรายเดินไม่เป็นจังหวะเพื่อหลอกมัน", "A giant sandworm that tunnels under the dunes, feels the rhythm of footsteps and bursts up to bite. Desert folk walk out of step to fool it."],
  goldscarab:["ด้วงมูลสัตว์ที่ชาวอียิปต์โบราณบูชาเป็นสัญลักษณ์ของดวงอาทิตย์ ด้วงจริงกลิ้งก้อนมูลและใช้ทางช้างเผือกนำทางตอนกลางคืน ตัวนี้กระดองทองสะท้อนแดดจนร้อนจี๋", "The scarab, a dung beetle the ancient Egyptians worshipped as a sign of the sun. Real ones roll dung balls and steer by the Milky Way at night; this one's golden shell blazes in the sun."],
  sandgolem:["หุ่นทรายที่ลมทะเลทรายปั้นขึ้น ทรายถูกลมกัดเซาะจนเป็นรูปร่างเหมือนประติมากรรม ร่างนี้ได้วิญญาณจากเทพสุริยะจึงลุกเดินได้", "A golem shaped by the desert wind, which carves sand and sandstone into figures like sculpture. This one caught a spark from the sun god and stood up to walk."],
  mirage:["ภาพลวงตาที่เกิดจากแสงหักเหผ่านอากาศร้อนใกล้พื้น ทำให้เห็นเหมือนมีแอ่งน้ำกลางทราย ภาพนี้มีชีวิตและยั่วให้นักเดินทางหลงทางจนกระหายน้ำ", "A mirage, made when light bends through hot air near the ground so a shimmering pool seems to lie on the sand. This one is alive, and lures travellers off course until they die of thirst."],
  /* ---------- 22 Red Rock Canyon ---------- */
  redpuma:["เสือภูเขาสีน้ำตาลแดงที่กลมกลืนกับผาหินทราย กระโดดได้สูงห้าเมตรและไกลกว่าสิบเมตรแบบพูมาจริง ซุ่มรอบนชะง่อนผาแล้วกระโจนใส่เหยื่อ", "A red-brown mountain cat that blends into the sandstone cliffs; like a real puma it can leap five metres up and more than ten across. It waits on a ledge and springs down on its prey."],
  rockhawk:["เหยี่ยวเพเรกริน สัตว์ที่เร็วที่สุดในโลก ดิ่งลงจับนกด้วยความเร็วกว่า 300 กิโลเมตรต่อชั่วโมง หลังเทาเข้ม อกขาวมีลายขวาง มีแถบดำใต้ตาเหมือนหนวด ทำรังบนหน้าผาสูง", "The peregrine falcon, the fastest animal on earth, stooping on birds at over 300 km/h: slate-grey above, white and barred below, with a dark moustache under the eye. It nests on high cliffs."],
  rattleviper:["งูกะปะ งูพิษหัวสามเหลี่ยมลายสามเหลี่ยมสีเข้มบนหลัง นอนนิ่งพรางตัวกับใบไม้แห้งจนคนเหยียบ พิษทำให้เลือดไม่แข็งตัว ตัวในหุบผานี้มีสีแดงตามหินทราย", "The Malayan pit viper, triangle-headed with dark triangles down its back, lying so still among leaf litter that people tread on it; its venom stops blood from clotting. The canyon ones have turned red like the sandstone."],
  canyonspider:["ต่อหัวเสือแห่งผาหิน ต่อหัวเสือจริงเป็นต่อขนาดใหญ่ของไทย หัวสีส้ม ท้องลายน้ำตาลเหลือง เหล็กในต่อยได้ซ้ำหลายครั้งและพิษแรงมาก ถ้ารังถูกรบกวนจะออกมาไล่ต่อยเป็นฝูง", "The tiger hornet of the red cliffs. Real tiger hornets are Thailand's big hornets, orange-headed with banded brown and yellow abdomens; a hornet can sting again and again, and a disturbed nest pours out to chase you."],
  redgolem:["หินทรายแดงที่มีเหล็กออกไซด์จึงเป็นสีสนิม ชั้นหินบนตัวบอกอายุนับล้านปี ก้อนนี้หลุดจากหน้าผาแล้วเดินลาดตระเวนหุบเขา", "Red sandstone coloured rust by iron oxide, its layered bands recording millions of years. This boulder broke off the cliff and now patrols the canyon."],
  banditghost:["วิญญาณโจรที่เคยซุ่มปล้นกองคาราวานในหุบผา ถูกจับประหารแล้วแต่ยังไม่เลิกปล้น โพกผ้าคลุมหัวกันแดดและฝุ่นแบบโจรทะเลทราย", "The ghost of a bandit who once ambushed caravans in the canyon. He was caught and executed but never stopped robbing, his head wrapped against sun and dust like a desert raider."],
  /* ---------- 23 Lava Fields ---------- */
  magmaslime:["หินหนืดที่ร้อนกว่าพันองศาซึ่งไหลออกมาจากรอยแยกแล้วจับตัวเป็นก้อนมีชีวิต ผิวด้านนอกเย็นตัวเป็นเปลือกดำแต่ข้างในยังลุกโชน", "Molten rock at over a thousand degrees that oozed from a fissure and gathered into a living blob. Its skin cools into a dark crust while the core still glows."],
  firelizard:["ซาลาแมนเดอร์ในตำนานยุโรปเชื่อว่าเกิดจากไฟ เพราะเวลาจุดท่อนไม้ซาลาแมนเดอร์ที่ซ่อนอยู่จะวิ่งหนีออกมา ตัวนี้อาศัยในลาวาจริงและเลือดเป็นไฟ", "In European legend the salamander was born of fire, because real salamanders hiding in logs ran out when the logs were lit. This one truly lives in lava, and its blood burns."],
  ashbat:["ค้างคาวที่อาศัยในถ้ำลาวา เส้นเลือดในพังผืดปีกลุกเป็นสีส้ม ค้างคาวจริงระบายความร้อนผ่านปีกที่บาง ตัวนี้จึงทนร้อนได้มาก", "A bat of the lava tubes whose wing membranes glow orange along the veins. Real bats shed heat through their thin wings, which is how this one survives such heat."],
  lavaserpent:["งูที่ว่ายอยู่ในธารลาวา ผิวดำเหมือนหินบะซอลต์ ท้องและลายปล้องส้มเรืองเหมือนลาวาที่ไหลใต้เปลือกหิน ถ่มลูกไฟใส่ผู้บุกรุก", "A serpent that swims in rivers of lava, black as basalt above with a belly and bands glowing orange like lava flowing under a crust. It spits fireballs at intruders."],
  cinderimp:["ภูตไฟตัวเล็กจอมซนที่เกิดจากประกายไฟ ชอบจุดไฟเผาข้าวของแล้วหัวเราะ คล้ายผีเจ้าเล่ห์ในนิทานพื้นบ้านหลายชาติ", "A small mischievous fire sprite born from a spark, who loves to set things alight and laugh, like the trickster imps of many folk tales."],
  embergolem:["ก้อนหินบะซอลต์ที่ข้างในยังร้อน รอยแตกบนผิวมีแสงลาวาเรืองออกมา หินนี้ค่อย ๆ เย็นตัวมาหลายร้อยปีแต่ไฟข้างในไม่ยอมดับ", "A basalt boulder still hot inside, lava light glowing through the cracks in its skin. It has been cooling for centuries, but the fire inside will not go out."],
  /* ---------- 24 Ashen Forest ---------- */
  ashwolf:["หมาป่าที่รอดจากไฟป่ามาได้ ขนเปื้อนเถ้าเป็นสีเทา หมาป่าจริงล่าเป็นฝูงและสื่อสารด้วยการหอน ฝูงนี้ล่าในควันไฟที่เหยื่อมองไม่เห็น", "A wolf that survived the wildfire, its coat stained grey with ash. Real wolves hunt in packs and talk by howling; this pack hunts inside the smoke where prey cannot see."],
  charredent:["ตอไม้ใหญ่ที่ถูกไฟเผาจนดำแต่รากยังไม่ตาย ไม้บางชนิดในป่าเต็งรังทนไฟและแตกยอดใหม่ได้ ตอนี้กลับลุกขึ้นเดินและแกว่งกิ่งที่ยังคุไฟอยู่", "A great stump burned black whose roots still live; some trees of the dry dipterocarp forest survive fire and resprout. This one got up and walks, swinging branches that still smoulder."],
  smokewisp:["ควันไฟป่าที่ม้วนตัวเป็นก้อนมีหน้าตา ควันไฟป่าทางเหนือของไทยทำให้ฝุ่นพิษเต็มฟ้าทุกหน้าแล้ง วิญญาณควันนี้ทำให้หายใจไม่ออก", "Wildfire smoke rolled into a cloud with a face. Forest fires choke northern Thailand with haze every dry season, and this smoke spirit leaves you gasping for breath."],
  cinderbeetle:["ด้วงไฟป่า ด้วงจริงบางชนิดมีอวัยวะรับรังสีความร้อนจับไฟป่าได้ไกลหลายสิบกิโลเมตรเพื่อวางไข่ในไม้ที่เพิ่งไหม้ ตัวนี้เปลือกเป็นถ่านคุแดง", "A fire beetle; some real beetles have infrared sensors that find forest fires tens of kilometres away so they can lay eggs in freshly burned wood. This one's shell is glowing charcoal."],
  phoenixchick:["ลูกนกเพลิงที่เพิ่งเกิดใหม่จากกองเถ้า ตามตำนานนกเพลิงจะเผาตัวเองเมื่อแก่แล้วเกิดใหม่จากเถ้า ตัวเล็กแต่ไฟแรงเกินตัว", "A phoenix chick just reborn from the ashes; legend says the phoenix burns itself up in old age and rises again from the cinders. Small, but its fire is fierce."],
  ashghoul:["ผีที่ตายในไฟป่าและยังเร่ร่อนในป่าที่ไหม้ ตัวเปื้อนเถ้าดำ ผมหงอกขาวเพราะความร้อน ออกหากินเฉพาะตอนกลางคืน", "The ghost of someone who died in the wildfire, still roaming the burned forest smeared with black ash, hair bleached white by the heat. It only comes out at night."],
  /* ---------- 25 Agni Crater ---------- */
  lavadrake:["มังกรลาวาวัยเยาว์ ตัวยาวเหมือนจระเข้ ผิวดำแดง ลายเหลืองเรือง อาศัยริมปากปล่องและพ่นไอร้อนใส่ใครก็ตามที่เข้าใกล้รัง", "A young lava drake, long-bodied like a crocodile, black-red with glowing yellow markings. It lives on the crater rim and breathes scalding vapour at anyone near its nest."],
  firedjinn:["ญินในตำนานอาหรับเป็นสิ่งมีชีวิตที่สร้างจากไฟไร้ควัน ตนนี้ถูกผนึกไว้ในปล่องภูเขาไฟ ใบหน้ามีเขาและเปลวไฟพลิ้วเป็นหาง", "In Arabian lore the djinn are beings made from smokeless fire. This one was sealed in the volcano's throat, a horned face with flames streaming behind like tails."],
  magmatoad:["คางคกที่อาศัยตามขอบลาวา ผิวหยาบเป็นตุ่ม คางคกจริงมีต่อมพิษหลังตาที่ทำให้สัตว์ผู้ล่าป่วย ตุ่มบนตัวนี้มีพิษร้อนเหมือนถ่าน", "A toad living on the lava's edge with lumpy, warty skin. Real toads have poison glands behind their eyes that sicken predators; this one's warts burn like coals."],
  flamegaruda:["ครุฑหนุ่มที่บินผ่านไฟภูเขาไฟจนขนปีกลุกเป็นเปลว ในคติไทยครุฑมีฤทธิ์บินได้เร็วและแข็งแกร่ง ตัวนี้ยังไม่ได้มงกุฎแต่ไฟแรงยิ่งกว่าครุฑทั่วไป", "A young garuda who flew through the volcano's fire until its wing feathers burst into flame. In Thai lore the garuda is swift and mighty; this one has no crown yet, but burns hotter than any other."],
  obsidiangolem:["หินออบซิเดียน แก้วภูเขาไฟสีดำที่เกิดจากลาวาเย็นตัวเร็วจนไม่มีเวลาตกผลึก คมกว่ามีดโกน คนโบราณใช้ทำหัวหอก ร่างนี้มีเศษแก้วคมงอกทั่วตัว", "Obsidian, black volcanic glass formed when lava cools too fast to crystallise, sharper than a razor and used by ancient peoples for spear points. Jagged glass shards grow all over this one."],
  agnipriest:["นักบวชที่บูชาพระอัคนี เทพแห่งไฟในพระเวท พิธีบูชาไฟหรือโหมกูณฑ์เป็นพิธีพราหมณ์ที่เก่าแก่ที่สุด นักบวชพวกนี้ใช้ไฟศักดิ์สิทธิ์เป็นอาวุธ", "A priest of Agni, the fire god of the Vedas; the fire offering, homa, is among the oldest Brahmin rites. These priests use the sacred flame as a weapon."],
  /* ---------- 26 Frozen Lake ---------- */
  frosttoad:["คางคกที่จำศีลในโคลนใต้ทะเลสาบน้ำแข็ง กบบางชนิดในเขตหนาวยอมให้ตัวเองแข็งเป็นน้ำแข็งทั้งตัวแล้วฟื้นขึ้นเมื่อฤดูใบไม้ผลิ ตัวนี้ฟื้นมาแต่ยังเย็นเยียบ", "A toad that hibernates in the mud under the frozen lake. Some cold-country frogs let themselves freeze solid and revive in spring; this one revived but is still ice cold."],
  snowfox:["จิ้งจอกขั้วโลก ขนขาวในฤดูหนาวและเปลี่ยนเป็นน้ำตาลในฤดูร้อน หางพวงใหญ่ใช้ห่มตัวเวลานอน ได้ยินเสียงเหยื่อใต้หิมะแล้วกระโจนดำลงไปจับ", "The Arctic fox, white in winter and brown in summer, curling its bushy tail around itself to sleep. It hears prey moving under the snow and pounces head-first to catch it."],
  icefisher:["นกกระเต็นขนฟ้าครามที่จับปลาตามรูน้ำแข็งบนทะเลสาบ เกาะนิ่งอยู่บนก้อนน้ำแข็งแล้วพุ่งลงน้ำเร็วราวลูกธนู ปากยาวแหลมของมันจิกได้แรงกว่าที่คิด", "A sky-blue kingfisher that fishes the holes in the frozen lake, perching still on the ice and diving like an arrow. Its long sharp bill strikes harder than you would think."],
  frostjelly:["เจลลี่ที่น้ำค้างแข็งเกาะจนมีเกล็ดน้ำแข็งแหลมรอบตัว เหมือนน้ำค้างแข็งบนใบไม้ยามเช้าในฤดูหนาว ยิงเกล็ดน้ำแข็งใส่ผู้ที่เข้าใกล้", "A jelly furred with spiky hoarfrost, like the frost on leaves on a winter morning. It flings shards of ice at anyone who comes close."],
  snowowl:["นกเค้าหิมะ ขนขาวแทบทั้งตัว ตัวเมียมีลายขวางสีเข้ม ล่าในเวลากลางวันซึ่งต่างจากนกเค้าส่วนใหญ่ เพราะฤดูร้อนขั้วโลกไม่มีกลางคืน", "The snowy owl, almost all white, the female barred with dark bands. Unlike most owls it hunts by day, since the polar summer has no night."],
  icecrab:["ปูในน้ำเย็นจัดเหมือนปูราชาอลาสกาที่ตัวโตเพราะน้ำเย็นทำให้เติบโตช้าแต่อายุยืน ก้ามใหญ่ทุบน้ำแข็งได้", "A crab of freezing water like the king crabs of Alaska, which grow big because the cold makes them grow slowly and live long. Its great claw cracks ice."],
  /* ---------- 27 Eternal Ice Cave ---------- */
  icebat:["ค้างคาวที่จำศีลในถ้ำน้ำแข็ง ค้างคาวจริงลดอุณหภูมิร่างกายลงเกือบศูนย์องศาตอนจำศีล ปีกของตัวนี้มีน้ำค้างแข็งเกาะเป็นลายเรืองแสง", "A bat that hibernates in the ice cave; real bats let their body temperature fall almost to freezing while hibernating. Frost glitters in glowing veins across this one's wings."],
  frostspider:["แตนที่ปีกและเปลือกเป็นผลึกน้ำแข็ง แตนจริงเอวคอดเล็ก ลำตัวเรียวยาว และกระพือปีกได้หลายร้อยครั้งต่อวินาที เสียงหึ่งของมันก้องไปทั้งถ้ำ", "A wasp whose wings and shell are ice crystal. Real wasps have a narrow waist and a slender body and beat their wings hundreds of times a second; its buzz echoes through the whole cave."],
  crystalgolem:["หุ่นผลึกน้ำแข็งที่เกิดจากน้ำแข็งในถ้ำอัดตัวนับพันปีจนใสและแข็งเหมือนแก้ว ผลึกแหลมงอกตามไหล่และหลัง", "A golem of cave ice pressed for thousands of years until clear and hard as glass, with sharp crystals growing along its shoulders and back."],
  iceworm:["หนอนน้ำแข็ง หนอนจริงชนิดนี้อาศัยในธารน้ำแข็งที่อลาสกา ถ้าอุ่นกว่าห้าองศาตัวจะละลาย ตัวในถ้ำนี้โตผิดปกติและมุดน้ำแข็งเป็นอุโมงค์", "Ice worms really exist, living inside Alaskan glaciers and melting if it gets above about five degrees. This cave's worms have grown huge and bore tunnels through the ice."],
  frostwisp:["วิญญาณความหนาวที่มีผลึกน้ำแข็งแหลมยื่นรอบตัว ลมหายใจมันทำให้ทุกอย่างรอบข้างจับเป็นเกล็ดน้ำแข็งเหมือนลมหนาวจัดที่ทำให้ผิวแตก", "A spirit of the deep cold bristling with ice spikes. Its breath frosts over everything around it, like a killing wind that cracks the skin."],
  yeti:["เยติ มนุษย์หิมะในตำนานชาวเชอร์ปาแห่งหิมาลัย นักสำรวจที่ตามหาพบว่ารอยเท้าและขนส่วนใหญ่เป็นของหมีหิมาลัย ตัวนี้มีจริง ขนขาวยาวและแข็งแรงมหาศาล", "The yeti of Sherpa legend in the Himalaya; expeditions that hunted it found the footprints and hair mostly belonged to Himalayan bears. This one is real, long-haired, white and enormously strong."],
  /* ---------- 28 Millennial Glacier ---------- */
  mammoth:["ช้างแมมมอธขนยาว มีขนหนาสองชั้น หูเล็กกันความหนาว งาโค้งยาวใช้กวาดหิมะหาหญ้า สูญพันธุ์ไปเมื่อราวสี่พันปีก่อน ฝูงนี้ถูกน้ำแข็งแช่ไว้แล้วตื่นขึ้นมา", "The woolly mammoth, with a double coat of fur, small ears against the cold and long curved tusks to sweep snow off the grass. It died out about four thousand years ago; this herd was frozen in the ice and has woken up."],
  icewolf:["หมาป่าขาวแห่งธารน้ำแข็ง เหมือนหมาป่าอาร์กติกที่ขนขาวทั้งปีและล่าวัวมัสก์เป็นฝูง วิ่งได้ทั้งวันบนหิมะโดยไม่หยุด", "A white glacier wolf like the Arctic wolf, which stays white all year and hunts musk oxen in packs. It can run across the snow all day without stopping."],
  glacierhawk:["อินทรีทะเลสเตลเลอร์ อินทรีที่หนักที่สุดในโลก ตัวดำน้ำตาลมีหัวไหล่และหางสีขาว ปากเหลืองใหญ่หนา จับปลาแซลมอนจากรอยแยกน้ำแข็ง", "Like Steller's sea eagle, the heaviest eagle in the world: dark brown with white shoulders and tail and a massive yellow bill, snatching salmon from cracks in the ice."],
  frostgiant:["ยักษ์ธารน้ำแข็ง คล้ายยักษ์น้ำแข็งในตำนานนอร์ส ตัวใหญ่เท่าภูเขาน้ำแข็ง เคราขาวยาว เดินตามธารน้ำแข็งที่ไหลช้ามาพันปี", "A glacier giant like the frost giants of Norse myth, huge as an iceberg with a long white beard, walking the slow glacier that has crept for a thousand years."],
  iceslime:["เมือกใสที่เกิดจากน้ำแข็งละลายแล้วแข็งตัวซ้ำไปมาจนใสไร้สี เหมือนน้ำแข็งสีฟ้าใสในธารน้ำแข็งที่ไม่มีฟองอากาศเหลืออยู่ มองแทบไม่เห็นบนพื้นน้ำแข็ง", "A clear ooze of ice melted and refrozen again and again until colourless, like the bubble-free blue ice deep in a glacier. It is almost invisible on the ice."],
  icewyrm:["นาคน้ำแข็งที่ขดตัวอยู่ใต้ธารน้ำแข็ง ตามคติไทยนาคเป็นผู้ให้น้ำ ตัวนี้จึงคุมน้ำในธารน้ำแข็งทั้งหมด และพ่นลมเย็นจนน้ำกลายเป็นหิน", "An ice naga coiled beneath the glacier. In Thai lore the nagas give the world its water, so this one rules every drop in the ice, and breathes cold that turns water to stone."],
  /* ---------- 29 Citadel of the Snow King ---------- */
  frostknight:["หมีขาวตัวมหึมาที่ยึดป้อมน้ำแข็งเป็นถิ่น ขนหนาสองชั้นกับไขมันใต้ผิวทำให้ไม่หนาว ตบทีเดียวทำลายกำแพงน้ำแข็งได้ หมีขาวจริงเป็นสัตว์กินเนื้อบนบกที่ใหญ่ที่สุดในโลก", "A huge polar bear that has made the ice citadel its den, kept warm by a double coat and thick fat; one swipe breaks an ice wall. Real polar bears are the largest land carnivores on Earth."],
  icegargoyle:["การ์กอยล์ รูปปั้นสัตว์ประหลาดบนหลังคาโบสถ์ยุโรปที่ทำหน้าที่เป็นรางน้ำ ตัวนี้เป็นน้ำแข็ง มีเขาและปีกค้างคาว แข็งนิ่งบนหลังคาป้อมจนกว่าจะมีผู้บุกรุก", "A gargoyle, the monster statue on European church roofs that is really a rain spout. This one is ice, with horns and bat wings, frozen still on the citadel roof until intruders come."],
  snowlion:["สิงโตหิมะ สัตว์ศักดิ์สิทธิ์ของทิเบต ตัวขาว แผงคอสีเขียวคราม เป็นสัญลักษณ์ของความกล้าหาญและปรากฏบนธงทิเบต ตัวนี้เฝ้าประตูป้อมของพญาหิมะ", "The snow lion, sacred animal of Tibet, white with a turquoise mane, a symbol of fearlessness that appears on the Tibetan flag. This one guards the Snow King's gate."],
  frostwraith:["วิญญาณทหารที่แข็งตายบนกำแพงป้อม คลุมผ้าห่อศพสีน้ำเงินเข้ม มีน้ำแข็งแหลมงอกทั่วตัว ออกเดินยามเฉพาะตอนกลางคืน", "The ghost of a sentry who froze to death on the citadel wall, wrapped in a dark blue shroud bristling with icicles. It walks its rounds only at night."],
  icesentry:["ทหารผลึกที่พญาหิมะเสกขึ้นจากน้ำแข็ง มีอักขระเวทเรืองแสงไหลตามรอยต่อบนตัวคอยสั่งการ ยืนเฝ้าประตูไม่หลับไม่นอน", "A crystal soldier the Snow King conjured from ice, with runes of command glowing in the seams of its body. It guards the gate without sleep or rest."],
  frostnaga:["นาคราชหิมะ ตามตำนานนาคมีหลายตระกูลตามสีกายและถิ่น ตระกูลนี้อาศัยบนเขาหิมะ เกล็ดขาวดั่งน้ำแข็ง สวมมงกุฎ พ่นเกล็ดน้ำแข็งใส่ศัตรู", "A snow naga lord; legend sorts the nagas into clans by colour and home, and this clan lives on the snow peaks, ice-white and crowned, spitting shards of ice at its foes."],
  /* ---------- 30 Gate of Tavatimsa ---------- */
  devaguard:["เทวดาเฝ้าประตูสวรรค์ชั้นดาวดึงส์ สวรรค์ชั้นที่สองซึ่งพระอินทร์ปกครอง ใส่เสื้อคลุมทอง ถือพระขรรค์ เข้มงวดกับทุกคนที่ผ่านประตู", "A deva guarding the gate of Tavatimsa, the second heaven, ruled by Indra. Dressed in a golden cloak and holding a sword, it is strict with everyone who passes."],
  airavata:["ช้างเอราวัณ ช้างทรงของพระอินทร์ ในคติไทยวาดเป็นช้างเผือกสามเศียร คัมภีร์ว่ามีถึงสามสิบสามเศียร แต่ละเศียรมีงาเจ็ดงา ใช้เป็นตราของกรุงเทพมหานคร", "Erawan, Indra's mount, painted in Thai art as a three-headed white elephant; the scriptures give it thirty-three heads, each with seven tusks. It is the emblem of Bangkok."],
  heavenhamsa:["หงส์สวรรค์ขนขาวปีกทอง บินขึ้นลงระหว่างสระอโนดาตกับสวรรค์ ร้องเป็นแสงศักดิ์สิทธิ์ที่ทำลายสิ่งชั่วร้าย", "A heavenly hamsa, white with golden wings, flying between Lake Anodat and the heavens. Its call becomes holy light that burns away evil."],
  lightjelly:["ดวงแก้วสวรรค์ที่หลุดจากยอดปราสาทเวชยันต์ของพระอินทร์ มีวงแสงลอยอยู่เหนือดวง คอยยิงลำแสงใส่อสูรที่บุกขึ้นมา", "A heavenly crystal fallen from the spire of Indra's Vejayanta palace, a ring of light floating above it. It fires beams at the asuras storming the gate."],
  celestialnaga:["นาคสวรรค์ผู้เฝ้าประตูดาวดึงส์ ตามตำนาน นาคที่บำเพ็ญเพียรจนได้เป็นเทพจะได้ขึ้นมาอยู่สวรรค์ หงอนทองยาว ตาขาวเรืองแสง", "A celestial naga guarding the gate of Tavatimsa; legend says a naga who perfects its virtue may rise to heaven as a deva. It has a long golden crest and white glowing eyes."],
  starwisp:["ดาวตกดวงเล็กที่ตกค้างอยู่ที่ประตูสวรรค์ ทางช้างเผือกในคติไทยเรียกว่าทางเผือก ดาวน้อยดวงนี้หลงทางจากทางนั้นและลอยวนเฝ้าประตู", "A little shooting star stranded at heaven's gate. It lost its way from the Milky Way, which old Thai star-lore calls the white elephant road, and circles the gate on watch."],
  /* ---------- bosses ---------- */
  whitemonkeyking:["พญาลิงเผือก ลิงที่ขาดเม็ดสีจนขาวทั้งตัวพบได้ยากมาก ชาวบ้านจึงเชื่อว่าเป็นวานรศักดิ์สิทธิ์เชื้อสายหนุมาน มันคุมฝูงลิงทั้งป่าไผ่และเรียกลูกฝูงมาช่วยรบ", "The White Monkey King: albino monkeys are so rare that villagers take them for holy kin of Hanuman. It rules every troop in the bamboo and calls them in to fight beside it."],
  lotusturtle:["พญาเต่าบัวหลวงที่อายุหลายร้อยปีจนมีบัวงอกบนกระดอง เต่าบางชนิดอายุยืนกว่าสองร้อยปีจริง ตามความเชื่อไทยเต่าเป็นสัตว์มงคลแห่งอายุยืน มันเรียกเต่านาออกมาปกป้อง", "A turtle lord so old that lotuses grow from its shell; some tortoises really do live past two hundred, and in Thai belief the turtle stands for long life. It calls paddy turtles to shield it."],
  aikhiam:["ไอ้เคี่ยม พญาตะกวดยักษ์แห่งแม่น้ำเจ้าพระยา ชาวบ้านเล่าว่ามันยาวกว่าเรือแจว ลิ้นสองแฉกแลบลิ้มรสน้ำได้ไกลหลายคุ้งน้ำ และฟาดหางทีเดียวน้ำแตกเป็นวง", "Ai Khiam, the giant monitor king of the Chao Phraya: longer than a rowing boat, its forked tongue tastes the river bends away, and one lash of its tail bursts the water into rings"],
  marketmatron:["นางพรายแม่ค้าผู้คุมตลาดน้ำร้าง วิญญาณหญิงที่ตายพร้อมทรัพย์สมบัติ สวมสร้อยทองและผ้าคลุมเหมือนครั้งยังมีชีวิต ใช้มนต์เรียกวิญญาณแม่ค้าคนอื่นมาช่วย", "The wraith matron who rules the dead floating market, a woman who died with her fortune and still wears her gold necklace and shawl. She summons the other merchant ghosts to her aid."],
  dvarapala:["ทวารบาล ยักษ์ผู้เฝ้าประตูศาสนสถาน ยักษ์ศิลาคู่นี้ถือกระบองเหมือนทวารบาลจำหลักที่ปราสาทขอม เมื่อโกรธจะฟาดพื้นจนแผ่นดินสะเทือน", "A dvarapala, the giant who guards a sanctuary's door, carved in stone with a club like those at Khmer temples. When angered it strikes the ground until the earth shakes."],
  cavematriarch:["นางพญาต่อผู้ครองรังยักษ์ในถ้ำมืดมาหลายชั่วอายุ ในรังต่อจริงมีนางพญาตัวเดียวที่วางไข่ ตัวใหญ่กว่าต่องานมาก มันเรียกต่องานนับร้อยออกมาช่วยรบ", "The hornet queen who has ruled the giant nest in the dark cave for generations. A real nest has a single queen who lays all the eggs, far larger than her workers; she calls hundreds of workers out to fight."],
  saming:["เสือสมิง เสือที่กินคนมามากจนวิญญาณคนสิง แปลงเป็นคนได้ เสียงเรียกชื่อในป่าลึกตอนกลางคืนอาจเป็นมัน ตามความเชื่อทางเหนือและตะวันตกของไทย", "The saming of northern and western Thai belief, a tiger that has eaten so many people their spirits possess it and it can take human form. A voice calling your name in the deep forest at night may be the saming."],
  elderpop:["ผีปอบเฒ่าที่สิงคนมาหลายชั่วอายุ ตามความเชื่ออีสาน ผีปอบที่แก่กล้าจะมีลูกปอบหลายตัว ต้องใช้หมอธรรมหลายคนช่วยกันปราบ", "An elder phi pop that has possessed one host after another for generations; in Isan belief an old pop spawns many lesser ones and takes several exorcists working together to defeat."],
  khankhak:["พญาคันคาก จากตำนานอีสานเรื่องพญาคันคากที่ยกทัพกบเขียดขึ้นไปรบกับพญาแถนบนฟ้าจนได้ฝนกลับคืนมา เป็นที่มาของประเพณีบุญบั้งไฟขอฝน", "Phaya Khankhak, the Toad King of Isan legend, who led an army of frogs up to fight the sky god Thaen and won back the rain; the rocket festival of Bun Bang Fai comes from this tale."],
  templecolossus:["ราชสีห์ศิลาเทวาลัยขนาดมหึมา ตะไคร่น้ำเกาะเป็นแผงคอ และสวมมงกุฎทองที่ยังเหลืออยู่ เคยเป็นผู้เฝ้าทางขึ้นปราสาทใหญ่ที่สุด ตาลุกเป็นไฟเมื่อถูกปลุก", "A colossal stone temple lion with moss for a mane and a gold crown that has survived the centuries, once the guardian of the greatest stairway. Its eyes burn red when it wakes."],
  andamancrab:["ปูยักษ์อันดามัน ตัวโตกว่าปูมะพร้าวซึ่งเป็นสัตว์ขาปล้องบนบกที่ใหญ่ที่สุดในโลกและหนีบลูกมะพร้าวแตกได้ ก้ามข้างหนึ่งใหญ่ผิดส่วนทุบเรือประมงจมได้", "The Andaman colossus crab, bigger than the coconut crab, the largest land arthropod on earth that can crack coconuts. One oversized claw can sink a fishing boat."],
  seaogress:["นางผีเสื้อสมุทร ยักษินีในพระอภัยมณีที่หลงรักพระอภัยมณีและขังไว้ในถ้ำใต้ทะเล เมื่อพระอภัยหนีไปนางตามไล่จนถูกเป่าปี่ตาย แปลงร่างเป็นหญิงงามได้", "Nang Phisuea Samut, the ogress of Phra Aphai Mani, who fell in love with Phra Aphai and kept him in an undersea cave; she chased him when he fled and was killed by the music of his flute. She can take the form of a beautiful woman."],
  phantomgeneral:["แม่ทัพผีแห่งกรุงศรีอยุธยาที่ตายในศึกครั้งสุดท้ายก่อนกรุงแตก สวมเสื้อคลุมแดงหม่น ยังสั่งทัพทหารผีให้รักษาเมืองต่อไป", "A phantom general of Ayutthaya who died in the last battle before the city fell, still in his faded red cloak, ordering his ghost army to hold the city."],
  lordkotchasi:["พญาคชสีห์ราชาแห่งคชสีห์ทั้งปวง ขนทอง แผงคอแดง สวมมงกุฎ เป็นตราสมุหกลาโหม เมื่อคำรามป่าหิมพานต์ทั้งป่าเงียบกริบ", "Lord of all the kotchasi, golden with a red mane and crowned, the seal of the Minister of War. When it roars, the whole of Himmapan falls silent."],
  waterelephantking:["ราชาแห่งวารีกุญชร ครึ่งช้างครึ่งปลา เกล็ดและหางปลาเป็นสีทอง ครองสระอโนดาตทั้งหมด เรียกน้ำจากสระมาโจมตีและรักษาตัวเอง", "The king of the wari kunchon, half elephant and half fish with golden scales and tail, ruling all of Lake Anodat. It calls the lake's water to strike its foes and heal itself."],
  laplaelord:["เจ้าเมืองลับแล ผู้ตั้งกฎห้ามพูดปด ตามตำนาน ชายที่เข้าเมืองลับแลได้แต่งงานกับหญิงในเมือง แต่เมื่อพูดโกหกลูกเพียงครั้งเดียวก็ถูกขับออกพร้อมห่อขมิ้นที่กลายเป็นทองคำ", "The lord of Laplae who made the law against lying. In the legend a man who married a Laplae woman told his child one lie and was sent away with a bundle of turmeric that later turned to gold."],
  nagaking:["พญานาคราชแห่งบาดาล ห้าเศียรสวมมงกุฎ ตามความเชื่อลุ่มน้ำโขง พญานาคเป็นผู้ให้ฝนและพ่นบั้งไฟพญานาคขึ้นจากแม่น้ำโขงในคืนออกพรรษา", "The naga king of the underworld, five-headed and crowned. In Mekong belief the naga king brings the rain, and on the night that ends Buddhist Lent he shoots the 'naga fireballs' up from the river."],
  tenfacedogre:["ทศกัณฐ์ ยักษ์สิบหน้ายี่สิบมือ เจ้ากรุงลงกาในรามเกียรติ์ ผู้ลักพานางสีดา ถอดดวงใจฝากไว้กับฤๅษีจึงไม่มีใครฆ่าได้ จนหนุมานไปลวงเอามา", "Thotsakan, the ten-faced, twenty-armed demon king of Lanka in the Ramakien who abducted Sita. He hid his heart with a hermit so nobody could kill him, until Hanuman tricked it away."],
  garudaking:["พญาครุฑ พญานกพาหนะของพระนารายณ์ ตัวแดงปีกทอง ตามตำนานครุฑเป็นศัตรูของนาคตั้งแต่แม่ของทั้งสองพนันกัน ครุฑเป็นตราแผ่นดินของไทย", "The Garuda King, mount of Vishnu, red-bodied and gold-winged. Legend says garudas and nagas became enemies through a wager between their mothers; the garuda is Thailand's royal emblem."],
  vessavana:["ท้าวเวสสุวรรณ หนึ่งในท้าวจตุโลกบาลผู้ปกครองทิศเหนือและเป็นเจ้าแห่งยักษ์ทั้งปวง กายสีน้ำเงิน ถือกระบอง คนไทยบูชาเพื่อปัดเป่าภูตผี", "Vessavana, one of the Four Heavenly Kings, guardian of the north and lord of all yakshas: blue-skinned and holding a club. Thais pray to him to ward off ghosts."],
  scorpionking:["ราชาแมงป่องแห่งทะเลทราย กระดองทองเข้ม ตาแดง ตามตำนานอียิปต์มีเทพีเซลเคตผู้เป็นแมงป่องคอยคุ้มครองผู้ถูกพิษ ตัวนี้กลับเป็นต้นพิษเสียเอง", "The scorpion king of the dunes, deep gold with red eyes. Egyptian myth has Serket, a scorpion goddess who protects against venom; this one is the venom's source instead."],
  redcliffgiant:["ยักษ์ผาแดงที่หลับอยู่ในหน้าผาจนตัวเป็นสีหิน มีเขาสีกระดูก ชาวบ้านเชื่อว่าหินถล่มคือเวลาที่ยักษ์พลิกตัว", "The giant of the red cliffs, asleep in the rock so long his skin took its colour, with horns pale as bone. Villagers say rockfalls happen when he turns over in his sleep."],
  firenaga:["พญานาคเพลิงสามเศียรที่ครองทุ่งลาวา ตามคติไทย นาคบางตระกูลมีฤทธิ์พ่นไฟ ตัวนี้ดำแดงเหมือนลาวาที่เพิ่งเย็นตัว", "A three-headed fire naga lord ruling the lava fields; in Thai lore some naga clans breathe fire, and this one is black and red like freshly cooled lava."],
  ashwolfking:["ราชาหมาป่าเถ้า จ่าฝูงที่ใหญ่ที่สุดในฝูง หมาป่าจริงมีคู่จ่าฝูงซึ่งเป็นพ่อแม่ของสมาชิกทั้งฝูง แผงคอของมันยังคุไฟเหมือนถ่านไม่มอด", "The ash wolf king, biggest of the pack. A real pack is led by a breeding pair, the parents of every other member; this one's mane still smoulders like live coals."],
  agnilord:["จอมเวทผู้รับพลังจากพระอัคนีจนกายแดงดั่งไฟ ในพระเวทพระอัคนีเป็นผู้นำเครื่องเซ่นจากมนุษย์ไปถึงเทพ มันเผาทุกสิ่งที่ไม่ยอมบูชาไฟ", "A sorcerer so filled with Agni's power his skin burns red. In the Vedas Agni carries humanity's offerings up to the gods, and this one burns all who will not worship fire."],
  iceturtlelord:["พญาเต่าน้ำแข็งที่จำศีลใต้ทะเลสาบมาหลายร้อยปี เต่าน้ำจืดจริงบางชนิดหายใจทางผิวหนังได้ใต้น้ำแข็งตลอดฤดูหนาว กระดองเป็นน้ำแข็งหนาทึบ", "An ice turtle lord that has hibernated under the lake for centuries; some real freshwater turtles breathe through their skin under the ice all winter. Its shell is solid ice."],
  frostqueen:["ราชินีผึ้งน้ำแข็งผู้สวมมงกุฎ รวงผึ้งผลึกทั้งถ้ำนิรันดร์เป็นของนาง ผึ้งจริงทั้งรังคอยปกป้องราชินีและกระพือปีกปรับอุณหภูมิรัง นางเรียกผึ้งงานผลึกน้ำแข็งมาช่วยรบ", "The crowned Frost Bee Queen; every crystal comb in the eternal cave is hers. A real hive guards its queen and fans its wings to keep the nest at the right warmth; she calls her ice worker bees to fight."],
  mammothking:["พญาช้างแมมมอธ จ่าฝูงอาวุโส ช้างจริงมีแม่แปรกตัวเมียที่อายุมากที่สุดเป็นผู้นำและจำแหล่งน้ำได้ตลอดชีวิต ตัวนี้แผงขนหงอกขาวและตาเย็นเยียบ", "The mammoth king, eldest of the herd; real elephant herds follow the oldest matriarch, who remembers every water source for life. This one's mane has gone white and its eyes are ice cold."],
  snowking:["พญาหิมะผู้ครองป้อมน้ำแข็ง เคราขาวยาว เสื้อคลุมฟ้า เชื่อกันว่าลมหนาวทุกสายมาจากลมหายใจของพระองค์ เรียกทหารผลึกมาช่วยรบได้ไม่สิ้นสุด", "The Snow King who rules the ice citadel, long-bearded and blue-cloaked; every cold wind is said to be his breath. He calls up crystal soldiers without end."],
  asuraking:["ราชาอสูรไวรา ผู้นำทัพอสูรบุกประตูดาวดึงส์ ตามคติไตรภูมิอสูรรบกับเทวดาไม่รู้จบเพราะแค้นที่ถูกพระอินทร์ขับไล่ เขาทองยาว กายแดงคล้ำ", "Vaira, the asura king leading the assault on the gate of Tavatimsa. In the Traiphum the asuras war on the devas forever, bitter at being cast out by Indra; he has long golden horns and a dark crimson body."],
  ayutyaksha:["ยักษ์ทวารบาลที่เคยยืนเฝ้าประตูพระราชวังกรุงเก่า เมื่อกรุงแตกก็ยังไม่ยอมละหน้าที่ เดินตรวจซากกำแพงด้วยกระบองและฟันที่ยื่นพ้นริมฝีปาก", "A gate yaksha that once guarded the palace of the old capital; the city fell, but it never left its post and still walks the broken walls."],
  krahangluang:["กระหังเฒ่าแห่งกรุงเก่า ใช้กระด้งฝัดข้าวสองใบเป็นปีก และสากตำข้าวเป็นขาที่สาม โฉบลงมาจากหลังคาโบสถ์ร้างในคืนเดือนมืด", "An old krahang of the fallen capital: two rice-winnowing trays for wings and a rice pestle for a third leg, swooping from ruined chapel roofs on moonless nights."],
  moatkappa:["ตะพาบน้ำตัวโตที่ฝังตัวในโคลนก้นคูเมืองเก่า กระดองนิ่มเป็นหนัง จมูกยาวเหมือนท่อหายใจ ยืดคอฉกได้เร็วมาก ตำนานกัปปะคูเมืองอาจมาจากตัวมันนี่เอง", "A big softshell turtle buried in the mud of the old city moat: a leathery shell, a snorkel nose and a neck that strikes like a whip. The tale of the moat kappa may well have begun with it."],
  nangtani:["นางไม้ที่สิงอยู่ในต้นกล้วยตานี ปรากฏเป็นหญิงสาวนุ่งห่มใบตองในคืนเงียบ ใครตัดต้นกล้วยของนางจะถูกตามรังควาน", "The spirit of the wild-banana tree, a young woman dressed in banana leaves on quiet nights; whoever cuts her tree is haunted."],
  /* ---------- special ---------- */
  dummy:["หุ่นฟางที่ครูฝึกตั้งไว้ให้ซ้อมตี ไม่ตอบโต้และไม่มีวันพัง เหมาะสำหรับลองสกิลและวัดความแรง", "A straw dummy the trainers set up for practice. It never hits back and never breaks, perfect for testing skills and measuring damage."],
  crowncrystal:["ผลึกจักรพรรดิหัวใจของปราสาทในศึกชิงปราสาท กิลด์ใดทำลายได้จะยึดปราสาทนั้นไป", "The Crown Crystal, heart of a castle in the guild siege. Whichever guild shatters it takes the castle."]
};
if (typeof W3_LOREMAP !== 'undefined') Object.assign(MOB_LORE, W3_LOREMAP);
